\subsection{Proof of   Theorem~\ref{t7}}\label{lea8} 
Before delving into the details, we present our proof strategy. We establish a deviation bound between the team-optimal solution and the NE using gradient information. To accomplish this, we propose two projected gradient algorithms for finding the team-optimal solution and the NE. Subsequently, we treat the gradient difference as a perturbation term and derive the deviation bound based on the stability of perturbed systems.



Let us consider the following projected gradient algorithm for seeking the team-optimal solution, i.e, for $i\in\mathcal{N}$, 
\begin{equation}\label{team1}
    \dot{u}_i=\Pi_{{\Xi}_i}({u}_i-\gamma \nabla_{{u}_i}\mathcal{C}(\boldsymbol{u}))-{u}_i,
\end{equation}
Here,  $\Pi_{{\Xi}_i}:\mathbb{R}^{P_i}\rightarrow {\Xi}_i$ is the projection map,  defined as $\Pi_{{\Xi}_i}(x)=\operatorname{argmin}_{y\in {\Xi}_i} \|x-y\|$, and 
$\gamma$ is the stepsize satisfying $0<\gamma <\min\{\frac{2\kappa_1}{\nu_1^2},\frac{2\kappa_2}{\nu_2^2}\}$.
The compact form of \eqref{team1} can be written as
\begin{equation}\label{dynamics_team}
 \dot{\boldsymbol{u}}=\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma G(\boldsymbol{u}))-\boldsymbol{u}.   
\end{equation}
It is clear that the equilibrium of dynamics \eqref{dynamics_team} is $\boldsymbol{u}^*$.  Then we show that \eqref{dynamics_team} converges at an exponential rate.
Consider the  candidate Lyapunov function $V(\boldsymbol{u})=\frac{1}{2}\|\boldsymbol{u}-\boldsymbol{u}^{*}\|^2$. 
Its time derivative along the trajectory of \eqref{dynamics_team} is
\begin{equation*}
    \begin{aligned}
    \dot{V}(\boldsymbol{u})&=-(\boldsymbol{u}-\boldsymbol{u}^*)^T(\boldsymbol{u}-\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma G(\boldsymbol{u})))\\
    &=-(\boldsymbol{u}\!-\!\boldsymbol{u}^*)^T(\boldsymbol{u}\!-\!\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}\!-\!\gamma G(\boldsymbol{u}))\!\\
    &\quad\quad\quad\,\,-(\boldsymbol{u}^*\!-\!\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}^*\!-\!\gamma G(\boldsymbol{u}^*))))\\
    &=-\|\boldsymbol{u}-\boldsymbol{u}^*\|^2+(\boldsymbol{u}-\boldsymbol{u}^*)^T(\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma G(\boldsymbol{u}))\\
    &\quad\quad\quad\,\,-\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}^*-\gamma G(\boldsymbol{u}^*)))\\
    &\leq -\|\boldsymbol{u}-\boldsymbol{u}^*\|(\|\boldsymbol{u}\!-\!\boldsymbol{u}^*\|\!-\!\|\boldsymbol{u}\!-\!\gamma G(\boldsymbol{u})\!-\!\boldsymbol{u}^*\!-\!\gamma G(\boldsymbol{u}^*)\|).
\end{aligned}
\end{equation*}
Then since
\begin{equation*}
    \begin{aligned}
&\|\boldsymbol{u}-\boldsymbol{u}^*\|-\|\boldsymbol{u}-\gamma G(\boldsymbol{u})-\boldsymbol{u}^*-\gamma G(\boldsymbol{u}^*)\|\\
=&\frac{\|\boldsymbol{u}-\boldsymbol{u}^*\|-\|\boldsymbol{u}-\gamma G(\boldsymbol{u})-\boldsymbol{u}^*-\gamma G(\boldsymbol{u}^*)\|^2}{\|\boldsymbol{u}-\boldsymbol{u}^*\|+\|\boldsymbol{u}-\gamma G(\boldsymbol{u})-\boldsymbol{u}^*-\gamma G(\boldsymbol{u}^*)\|}\\
\geq & \frac{ 2\gamma(\boldsymbol{u}-\boldsymbol{u}^*)^T(G(\boldsymbol{u})-G(\boldsymbol{u}^*))-\gamma^2\|G(\boldsymbol{u})-G(\boldsymbol{u}^*)\|^2}{(2+\gamma\cdot \nu_1)\|\boldsymbol{u}-\boldsymbol{u}^*\|}\\
\geq & \frac{2\gamma \cdot\kappa_1-\gamma^2\cdot\kappa_1^2 }{2+\gamma \cdot \nu_1} \|\boldsymbol{u}-\boldsymbol{u}^*\|\\
=&\omega \|\boldsymbol{u}-\boldsymbol{u}^*\|,
\end{aligned}
\end{equation*}
we have
\begin{align}
     \dot{V}(\boldsymbol{u})\leq -\omega \|\boldsymbol{u}-\boldsymbol{u}^*\|^2\leq -2\omega V(\boldsymbol{u}).\nonumber
\end{align}
This represents the exponential convergence rate. 


Similarly, consider the NE-seeking algorithm for   DM $i$
\begin{align}
\dot{u}_i=\Pi_{{\Xi}_i}(\boldsymbol{u}-\gamma \nabla_{{u}_i}\mathcal{C}_i({u}_i,\boldsymbol{u}_{-i}))-{u}_i.\nonumber
\end{align} 
The compact form of the NE-seeking dynamics
is 
\begin{equation}\label{dynamics_ne}
\dot{\boldsymbol{u}}=\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma F(\boldsymbol{u}))-\boldsymbol{u}
\end{equation}
We can similarly prove that \eqref{dynamics_ne} converge to $\boldsymbol{u}^{\Diamond}$
with an exponential convergence rate. 
Then, let us denote 
\begin{align}
   \beta(\boldsymbol{u})=\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma F(\boldsymbol{u}))-\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma G(\boldsymbol{u})). \nonumber 
\end{align} 
We rewrite the NE-seeking dynamics \eqref{dynamics_ne} as 
\begin{align}\label{perturb}
        \dot{\boldsymbol{u}}&= \Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}\!-\!\gamma G(\boldsymbol{u}))\!-\!\boldsymbol{u}\!+\!\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}\!-\!\gamma F(\boldsymbol{u}))\!-\!\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}\!-\!\gamma G(\boldsymbol{u}))\notag\\
    &=\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma G(\boldsymbol{u}))-\boldsymbol{u}+\beta(\boldsymbol{u}),
\end{align}
which can be regarded a perturbed system of \eqref{dynamics_team}. 
%Then we have 
Moreover, since $\boldsymbol{\Xi}$ is compact, there exists a constant $\delta$ such that
\begin{equation*}
\begin{aligned}
    \|\beta(\boldsymbol{u})\|&= \|\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma F(\boldsymbol{u}))-\Pi_{\boldsymbol{\Xi}}(\boldsymbol{u}-\gamma G(\boldsymbol{u}))\|\\
    &\leq \|\gamma F(\boldsymbol{u})-\gamma G(\boldsymbol{u})\|\\
    & \leq \gamma \| F(\boldsymbol{u})- G(\boldsymbol{u})\|\\
    & \leq \gamma \delta.
\end{aligned}
\end{equation*}
%where 
%$m=\max\{\zeta,\gamma\}$ and 
%$\phi $ is a positive constant that bounds$\| F(\boldsymbol{u})- G(\boldsymbol{u})\|$.
%can be bounded by a positive constant $\phi$. 
Then the Lyapunov function $V(\boldsymbol{u})$ along the trajectories
of \eqref{perturb} satisfies 
\begin{equation*}
    \begin{aligned}
    \dot{V}(\boldsymbol{u})
    &\leq -\omega\|\boldsymbol{u}-\boldsymbol{u}^*\|^2+\|\frac{\partial{V}}{\partial \boldsymbol{u}}\|\|\beta(\boldsymbol{u})\|\\
     &\leq -\omega\|\boldsymbol{u}-\boldsymbol{u}^*\|^2+ \gamma\delta \|\boldsymbol{u}-\boldsymbol{u}^*\|\\
     &=-(1-s)\omega\|\boldsymbol{u}-\boldsymbol{u}^*\|^2-s \omega\|\boldsymbol{u}-\boldsymbol{u}^*\|^2+\gamma\delta \|\boldsymbol{u}-\boldsymbol{u}^*\|\\
     &\leq -(1-s)\omega\|\boldsymbol{u}-\boldsymbol{u}^*\|^2, \quad \forall \|\boldsymbol{u}-\boldsymbol{u}^*\|\geq \gamma\delta/s\omega.
\end{aligned}
\end{equation*}
Referring to \cite[Theorem 4.18]{khalil2002nonlinear}, 
when $V(\boldsymbol{u})\geq\frac{1}{2}(\gamma\delta/s\omega)^2$, we have
$\|\boldsymbol{u}-\boldsymbol{u}^*\|\geq \gamma\delta/s\omega$ and $\dot{V}(\boldsymbol{u})\leq  -2(1-s)\omega V(\boldsymbol{u})$. This implies
\begin{align*}
\|\boldsymbol{u}-\boldsymbol{u}^*\|^2 &\leq \sqrt{2V(\boldsymbol{u}(t_0))}e^{-(1-s)\omega(t-t_0)} \\
&\leq e^{-(1-s)\omega(t-t_0)}\|\boldsymbol{u}(t_0)-\boldsymbol{u}^*\|
\end{align*}
over the interval $[t_0,t_0+T)$ for some finite $T$. For $t\geq t_0+T$, we have
\begin{align*}
    \|\boldsymbol{u}-\boldsymbol{u}^*\|\leq \sqrt{2V(\boldsymbol{u})} \leq \gamma\delta/s\omega,
\end{align*}
and the proof is complete.
\hfill $\square$



