\title{\bf Delegation with Trust$<$T$>$: A Scalable, \\ Type- and Memory-Safe Alternative to Locks}
\date{}
\author{Noaman Ahmad <nahmad30@uic.edu>, Ben Baenen <bbaene2@uic.edu>, \\
Chen Chen <cchen262@uic.edu>, Jakob Eriksson <jakob@uic.edu>}
%\thispagestyle{empty}
