        \cmidrule(r){2-3} \cmidrule(r){4-5}
        & I2I & I2V & I2I & I2V\\ 
        \midrule
        $\uparrow$ Aesthe. Score~\cite{murray2012ava} & 4.16 & \textbf{4.30} & 4.17 & \textbf{4.38} \\
        $\uparrow$ Q-Align IAA$_\%$~\cite{wu2023qalign} & 12.65 & \textbf{23.48} & 14.59 & \textbf{23.46} \\
        $\uparrow$ Q-Align IQA$_\%$~\cite{wu2023qalign} & 35.43 & \textbf{45.80} & 35.06 & \textbf{44.42} \\
