Dynamic Passage Retrieval Module (\textit{DPRM}) integrates semantic alignment mechanism to address the issue of semantic mismatching. We cluster subquestions into multiple categories and train cluster-specific embeddings to align questions and helpful passages in the semantic space. Given subquestions processed through \textit{QDM} and \textit{SDQM}, we partition them into k clusters $\{C_1, \ldots, C_k \}$ using the k-means algorithm on their embeddings. For each cluster $C_i$, we fine-tune a LoRA block $M_{DPRM}^{C_i}$ to maximize the similarity between the subquestion $q \in {C_i}$ and the helpful passage p:
% $$ \max \sum_{(q, p) \in C_i} \log \left( \frac{E_q \cdot E_p}{\|E_q\| \|E_p\|} \right) $$
\begin{equation}
\max_{M_{DPRM}^{C_i}} \mathbb{E}_{(q, p) \in C_i} \log \left( \frac{\mathbf{E}_q \cdot \mathbf{E}_p}{\|\mathbf{E}_q\| \|\mathbf{E}_p\|} \right),
\end{equation}
where $E_q$ and $E_p$ are the embeddings from the final hidden state of the last layer of $M_{DPRM}^{C_i}$.


\subsection{Q-DREAM based Inference}
In this section, we offer a comprehensive overview of how \texttt{Q-DREAM} framework processes and generates an answer for the original question $Q_{ori}$. Algorithm \ref{alg:Q-DREAM_inference} presents the details of \texttt{Q-DREAM}. During the inference, we use all pre-trained models of the three modules.

\textbf{Question Decomposition. } In this process, we employ the $M_{QDM}$ to decompose the original question $Q_{ori}$ into multiple subquestions $Q_{sub}$, which is formulated as follows:
\begin{equation}
     \underset{Q_{sub}}{\arg \max} \ P(Q_{sub} \mid Q_{ori}; M_{QDM})
\end{equation}

Next, we process the subquestions in $Q_{sub}$ sequentially. If the subquestion $q_i$ does not depend on the answer to previous subquestion, then directly input to the \textit{DPRM} and retrieve the passage $p_{q_i}$. Otherwise, $q_i$ is sent to the next step. 

We determine whether a subquestion exhibits dependencies by checking if there is a "\#number\#" marker by itself.
As shown in Figure \ref{Method}, the decomposed Subquestion\_2 "Who is the child of the director from \#1\#?
" exhibits dependencies, with the marker "\#1\#" indicating that it depends on the answer to Subquestion\_1.



\begin{algorithm}[h]
\caption{The inference process of Q-DREAM }
\label{alg:Q-DREAM_inference}
\begin{algorithmic}[1]
% \REQUIRE $Q_{ori}, M_{QDM}, M_{SDOM}, M_{DRM}, M, {Q_{sub}\prime}, {P_{Q_{sub}\prime}} \leftarrow \emptyset$
% \initialize ${Q_{sub}\prime}, {P_{Q_{sub}\prime}} \leftarrow \emptyset$
\REQUIRE $M, M_{QDM}, M_{SDOM}, M_{DPRM},$ \\
\vspace{1mm}
\hspace*{8.0mm} $Q_{ori}, {Q_{sub}\prime} \leftarrow \emptyset, {P_{Q_{sub}\prime}} \leftarrow \emptyset$ \\
\vspace{1mm}
\ENSURE $A_{ori}$
\vspace{1mm}
%\hline
\hrule
\vspace{1mm}
\STATE $Q_{sub} = \{q_1, \ldots, q_n\} \leftarrow M_{QDM}(Q_{ori})$
\FOR{$i = 1$ to $n$}
    \IF{$q_i$ \text{depend on the answer to }$q_j$}
        \STATE ${{q_i}\prime} = M_{SDOM}(q_j, p_{q_j}, q_i)$
        \STATE ${{q_i}^*} = {{q_i}\prime}$
    \ELSE
        \STATE ${{q_i}^*} = {q_i}$
    \ENDIF
    \STATE${Q_{sub}\prime} \leftarrow 
    {Q_{sub}\prime} \cup \{{{q_i}^*}\}$
    \STATE$c_{{q_i}^*} = cluster({{q_i}^*})$, \text{Max\_Score = -1}
    \STATE$E_{{q_i}^*} = h_{Last}^{(M)} \leftarrow {M_{DPRM}^{c_{{q_i}^*}}}({{q_i}^*})$
    \FOR{$p_v$ to $P$}
        \STATE $E_{p_v} = h_{Last}^{(M)} \leftarrow {M_{DPRM}^{c_{{q_i}^*}}}({p_v})$
        \STATE $\text{score} = cos(E_{{q_i}^*}, E_{p_v})$ 
        \IF{\text{score $>$ Max\_Score}}
            \STATE \text{Max\_Score = score}
            \STATE $p_{{q_i}^*} = p_v$
        \ENDIF
    \ENDFOR
    \STATE${P_{Q_{sub}\prime}} \leftarrow 
    {P_{Q_{sub}\prime}} \cup \{p_{{q_i}^*}\}$
\ENDFOR

\STATE $A_{ori} = M(Q_{ori}, {Q_{sub}\prime}, {P_{Q_{sub}\prime}})$
\end{algorithmic}
\end{algorithm}



\textbf{Subquestion Dependency Optimizer. }
If subquestion $q_i$ depends on the answer to subquestion \#j\#, it is incomplete and cannot effectively retrieve relevant content. Therefore, we need to utilize subquestion $q_j$ and its retrieved passage $p_{q_j}$ that contains useful information for answering $q_j$, to optimize $q_i$, which is formulated as:
\begin{equation}
    \underset{{{q_i}\prime}}{\arg \max} \ P({{q_i}\prime} \mid q_j, p_{q_j}, q_i; M_{SDOM}) 
\end{equation}
where ${{q_i}\prime}$ is the reconstructed subquestion after optimization.


After optimization, reconstructed subquestion\_2 "Who is the child of Anjan Choudhury?" in Figure \ref{Method} becomes more complete by explicitly identifying 'Anjan Choudhury' as the director during the retrieval process. Moreover, this explicit reconstruction process acts as the Chain-of-Thought, which helps the answer generation model to improve the reasoning performance for multi-hop QA.

\textbf{Dynamic Passage Retrieval. }
In the Dynamic Passage Retrieval Module, each subquestion ${q_i}^*$ (where ${q_i}^*$ is either $q_i$ or ${{q_i}\prime}$) is clustered based on its semantic embedding and the corresponding LoRA block is indexed. Subsequently, ${q_i}^*$ and candidate passages $P = \{p_1, \ldots, p_m \}$ are input into $M^{c_{{q_i}^*}}_{DPRM}$ respectively. We obtain $E_{{q_i}^*}$ and $E_P = \{E_{p_1}, \ldots, E_{p_m} \}$ form the last hidden state of the last layer of $M^{c_{{q_i}^*}}_{DPRM}$ and select the passage with the highest score according to the following formula:

\begin{equation}
p_{{q_i}^*} = \underset{p_v \in P}{\arg \max} \
 f({E_{{q_i}^*}}, E_{p_v})
\end{equation}
where $f(\cdot)$ is a score function such as cosine similarity, and $p_{{q_i}^*}$ is the retrieved passage of ${q_i}^*$.
% \begin{equation}
% p_{{q_i}^*} = \arg \max_{{E_{p_i} \in E_P}} f({E_{{q_i}^*}}, E_{p_i})
% \end{equation}

% Finally, We integrate these subquestions and their corresponding retrieval passages to generate the answer.
% Finally, We get all subquestions and their corresponding retrieval passages for $Q_{ori}$ to generate the answer. The equation expression is as follows:

Finally, we replace the subquestions in $Q_{sub}$ that exhibit dependencies with those reconstructed from \textit{SDOM}, forming ${{Q_{sub}}\prime}$, and obtain the retrieved passages $P_{{{Q_{sub}}\prime}}$ with \textit{DPRM}. Then the original question $Q_{ori}$, the subquestions ${{Q_{sub}}\prime}$, and the retrieved passages $P_{{{Q_{sub}}\prime}}$ are input into the answer generation model $M$ to generate the answer, which is formulated as follows:
\begin{equation}
    \underset{{A_{ori}}}{\arg \max} \ P(A_{ori} \mid Q_{ori}, {{Q_{sub}}\prime}, P_{{{Q_{sub}}\prime}}; M)
\end{equation}
where $A_{ori}$ is the answer to the original question.

