\section{Extrapolated regularization}
\label{section:extrap_reg}

First, subtraction is used in the integrals~\eqref{Stokes_SL} and~\eqref{Stokes_DL},
\begin{equation}
\label{Stokes_SL1}
	u_i(\bd{y}) = \frac{1}{8\pi}\int_\Gamma S_{ij}(\bd{y,x})\, [f_j(\bd{x}) - f_k(\bd{x}_0)n_k(\bd{x}_0)n_j(\bd{x})] \, dS(\bd{x}),
\end{equation}
\begin{equation}
\label{Stokes_DL1}
	v_i(\bd{y}) = \frac{1}{8\pi}\int_\Gamma T_{ijk} (\bd{y,x})\, [q_j(\bd{x}) - q_j(\bd{x}_0)] \, n_k(\bd{x})\, dS(\bd{x}) + \chi(\bd{y})\, q_i(\bd{x}_0),
\end{equation}
where $\bd{x}_0$ is the closest point on $\Gamma$, and $\chi(\bd{y})=1,0,1/2$ when $\bd{y}$ is inside, outside, or on $\Gamma$, respectively. In addition, as explained in~\cite{extrap}, the stresslet kernel is rewritten as follows,
\begin{equation}
\label{Tsplit}
	T_{ijk} =  T_{ijk}^{(1)} + T_{ijk}^{(2)} = - 6\left(\frac{t_{ijk}^{(1)}}{r^3} + \frac{t_{ijk}^{(2)} - (r^2 - b^2)\, t_{ijk}^{(1)}}{r^5}\right),
\end{equation}
with
\begin{equation}
	t_{ijk}^{(1)}  = bn_in_jn_k - (\hat{x}_i n_j n_k + n_i\hat{x}_j n_k + n_i n_j \hat{x}_k),
\end{equation}
\begin{equation}
	t_{ijk}^{(2)} = b(\hat{x}_i\hat{x}_j n_k + \hat{x}_i n_j\hat{x}_k + n_i\hat{x}_j\hat{x}_k) - \hat{x}_i\hat{x}_j\hat{x}_k,
\end{equation}
where $n_i$ and $\hat{x}_i$ are the $i$th components of $\bd{n}_0$ and $\hat{\bd{x}} = \bd{x}-\bd{x}_0$.

We compute~\eqref{Stokes_SL1} and~\eqref{Stokes_DL1} as 
\begin{equation}
\label{Stokes_SL2}
	u^\delta_i(\bd{y}) = \frac{1}{8\pi}\int_\Gamma S^\delta_{ij}(\bd{y,x})\, [f_j(\bd{x}) - f_k(\bd{x}_0)n_k(\bd{x}_0)n_j(\bd{x})] \, dS(\bd{x}),
\end{equation}
\begin{equation}
\label{Stokes_DL2}
	v^\delta_i(\bd{y}) = \frac{1}{8\pi}\int_\Gamma T^\delta_{ijk} (\bd{y,x}) \, [q_j(\bd{x}) - q_j(\bd{x}_0)] \, n_k(\bd{x})\, dS(\bd{x}) + \chi(\bd{y})\, q_i(\bd{x}_0),
\end{equation}
with $S_{ij}$ and $T_{ijk}$ replaced with the regularized versions,
\begin{equation}
\label{Sreg} 
	S_{ij}^\delta(\bd{y,x}) = \frac{\delta_{ij}}{r}\, s_1(r/\delta) + \frac{(y_i - x_i)(y_j - x_j)}{r^3}\, s_2(r/\delta)\,,
\end{equation}
\begin{equation}
\label{Treg} 
	T_{ijk}^\delta = T_{ijk}^{(1)}\, s_2(r/\delta) + T_{ijk}^{(2)}\, s_3(r/\delta),
\end{equation}
where 
\begin{equation}
\label{s1}
    s_1(r) = \erf(r) = \frac{2}{\sqrt{\pi}}\int_0^r e^{-s^2}\,ds,
\end{equation}
\begin{equation}
\label{s2}
    s_2(r) = \erf(r) - \frac{2}{\sqrt{\pi}}\, r \, e^{-r^2},
\end{equation}
\begin{equation}
\label{s3}
    s_3(r) = \erf(r) - \frac{2}{\sqrt{\pi}}\left(r + \frac23 r^3 \right) e^{-r^2}.
\end{equation}
Since $\erf(r/\delta) \to 1$ rapidly as $r/\delta$ increases, this regularization has a localized effect. This is discussed in more detail in Sec.~\ref{section:local_tree}.


The regularization error, namely, $u^\delta - u$ or $v^\delta-v$, is typically $O(\delta)$.
If $\bd{y}$ is near the surface, then we write $\bd{y} = \bd{x}_0 + b\bd{n}$, where $\bd{x}_0$ is the closest point on $\Gamma$, $\bd{n}$ is the outward normal vector at $\bd{x}_0$, and $b$ is the signed distance.  From a series expansion for $\bd{x}$ near $\bd{x}_0$ and $b$ near $0$, it was shown in~\cite{extrap} that
\begin{equation}
	\label{extrap_eqn}
	u_i(\bd{y}) + c_1 \rho I_0(\lambda) + c_2\rho^3 I_2(\lambda) = u_i^\delta (\bd{y}) + O(\delta^5),
\end{equation}
uniformly for $\bd{y}$ near the surface,
where $\lambda = b/\delta$, $\rho = \delta/h$, $c_1$ and $c_2$ are unknown coefficients, and $I_0$ and $I_2$ are integrals occurring in the derivation that are known explicitly,
\begin{equation}
	\label{I0}
	I_0(\lambda) = e^{-\lambda^2}/\sqrt{\pi} - |\lambda|\erfc|\lambda|,
\end{equation}
\begin{equation}
	\label{I2}
	I_2(\lambda) = \frac23\left((\frac12 - \lambda^2) e^{-\lambda^2}/\sqrt{\pi} + |\lambda|^3 \erfc|\lambda| \right),
\end{equation}
where $\erfc = 1 - \erf$. It is important that $c_1, c_2$ do not depend on $\delta$ or $\lambda$.
To obtain an accurate value of $u_i$, we calculate the regularized integrals $u_i^\delta$ for three different choices of $\delta$, with the same grid size $h$, resulting in a system of three equations with three unknowns.  We can then solve for the exact integral $u_i$ within error $\delta^5$. We typically choose $\delta_i = \rho_i h$ with $\rho_i = 3, 4, 5$. This procedure, and the equations~\eqref{extrap_eqn}-\eqref{I2}, are identical for the stresslet integral $v_i^\delta$ in~\eqref{Stokes_DL2}.


\subsection{Evaluation on the surface}
\label{subsec:eval_surf}

When the integrals need to be evaluated on the surface, e.g., when solving integral equations, the extrapolated regularization can be used as described, but a more direct method would be to replace the smoothing factors $s$ in~\eqref{s1}-\eqref{s3} with modified functions~\cite{tlupova-beale-19, novel},
\begin{equation}
    s_1^\sharp(r) = \erf(r) + \frac{2}{3\sqrt{\pi}} \left(5r - 2r^3\right) e^{-r^2},
\end{equation}
\begin{equation} 
    s_2^\sharp(r) = \erf(r) - \frac{2}{3\sqrt{\pi}} \left(3r - 14r^3 + 4r^5\right) e^{-r^2},
\end{equation}
\begin{equation}
    s_3^\sharp(r) = \erf(r) - \frac{2}{9\sqrt{\pi}} \left(9r + 6r^3 -4r^5\right) e^{-r^2}.
\end{equation}
Using these functions to regularize the kernels will result in $O(\delta^5)$ accuracy directly without the need for extrapolation. 


\subsection{Quadrature}
\label{subsec:quadrature}

We briefly discuss the quadrature rule for surface integrals introduced in~\cite{wilson-10, byw} and used in~\cite{extrap}. The surface is covered with a three-dimensional grid with spacing $h$. A set $\Gamma_3$ of quadrature points have the form $\bd{x} = (ih,jh,x_3)$ such that their projections on the $(x_1,x_2)$ plane are grid points, and $|\bd{n}(\bd{x}) \cdot \bd{e}_3| \geq \cos\theta$, where $\bd{n}(\bd{x})$ is the unit normal at $\bd{x}$, and we take $\theta = 70^o$. Sets $\Gamma_1$ and $\Gamma_2$ are defined similarly. For a function $f$ on the surface the integral is computed as
\begin{equation} 
    \label{quadrature}
    \int_\Gamma f(\bd{x})\,dS(\bd{x}) \,\approx\, \sum_{i=1}^3 \sum_{\bd{x} \in \Gamma_i} f(\bd{x})w_i(\bd{x}) \,,
    \qquad w_i(\bd{x}) = \frac{\psi_i(\bd{n}(\bd{x}))}{|n_i(\bd{x})|} \,h^2. 
\end{equation}
The weights $w_i$ are determined by a partition of unity $\psi_1, \psi_2, \psi_3$ on the unit sphere that is applied to the normal vector $\bd{n} = (n_1,n_2,n_3)$ at each point.  This is done by using the bump function
\begin{equation} 
    b(r) = \exp(2 r^2/(r^2-1))\,, \quad |r|<1\,; \qquad
    b(r) =  0\,, \quad |r| \geq 1,              
\end{equation} 
and defining
\begin{equation} 
    \beta_i(\bd{n}) = b(\cos^{-1}|n_i|)/\theta) \,, \quad \psi_i(\bd{n}) = \beta_i(\bd{n})/\left(\sum_{j=1}^3 \beta_j(\bd{n})\right).  
\end{equation}
The quadrature rule~\eqref{quadrature} has high order accuracy as allowed by the smoothness of the surface and the integrand. The weights cut off the sum in each plane, and each sum has the character of the trapezoidal rule without boundary; see~\cite{wilson-10}. For the full discussion of the error we refer to~\cite{extrap, neglect, byw}. We only note here that the quadrature error is small for $\delta/h\geq 2$ and decreases rapidly as $\delta/h$ increases. For moderate resolution sizes, setting $\delta=\rho h$, with $\rho=2,3,4$ or $\rho=3,4,5$, should work well in most cases, resulting in about $O(h^5)$ convergence. To ensure that the regularization error dominates the discretization error for small $h$ we can choose $\delta$ proportional to $h^q$, with $q < 1$, so that $\delta/h$ increases as $h \to 0$.


