%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition}\label{biharmonic:propEdit}
Let  $\Omega\in \R^d$ be a bounded domain ($\Omega$ is not necessarily a polytope). Suppose that 
$\bu$, ${\bm f}$, $p$,  $\phi$ satisfy \eqref{Model:Original} and are smooth. Then there holds
%
\begin{align}\label{eqn:BiharmonicEdit}
-\Delta^2 \bu = {\bm \psi}
\quad \mbox{with}\quad
{\bm \psi}:=	\Delta (\nab \phi) +\nu^{-1}[\Delta {\bm f}-\nab (\nab\cdot {\bm f})].
\end{align}
%
Furthermore, the quantities ${\bm \psi}$ and $\nu^{-1} \Delta {\bm f}-\nu^{-1}\nab (\nab \cdot {\bm f})$ are independent of both the pressure $p$ and the constant kinematic viscosity $\nu$ due to
%
\begin{equation}\label{f:nop}
\nu^{-1}[\Delta {\bm f}-\nab (\nab \cdot {\bm f})]=-\Delta^2 \bu+\nab (\nab \cdot \Delta \bu).
\end{equation}
%
\end{proposition}

\begin{proof}
From $-\nu \Delta \bu + \nab p = {\bm f}$ in \eqref{Model:Original},
we have $\nab p={\bm f}+\nu \Delta \bu $ and hence
\begin{align*}
\nab \Delta p =\nab ( \nab \cdot \nab p) = \nab \big(\nab\cdot {\bm f} +\nu \nab \cdot \Delta \bu\big) = \nab (\nab \cdot {\bm f}) -\nu \Delta \nab \phi,
\end{align*}
where we used $-\nab\cdot \bu = \phi$.
Using ${\bm f}=-\nu \Delta \bu + \nab p$ and the above identity, we deduce
%
\begin{align*}
\nu^{-1} \Delta {\bm f} = \nu^{-1} \Delta (-\nu \Delta \bu+\nab p) = -\Delta^2 \bu+\nu^{-1} \nab (\nab \cdot {\bm f}) -\Delta \nab \phi,
\end{align*}
where we used the simple fact $\Delta (\nab p)=\nab \Delta p$.
Rearranging the terms in this identity yields \eqref{eqn:BiharmonicEdit}.

On the other hand, we deduce from ${\bm f}=-\nu \Delta \bu + \nab p$ that
\[
\nu^{-1}\Delta {\bm f}=-\Delta^2 \bu+\nu^{-1} \Delta \nab p
\quad \mbox{and}\quad
\nu^{-1} \nab (\nab \cdot {\bm f})=-\nab (\nab \cdot \Delta \bu)+\nu^{-1} \nab (\nab\cdot \nab p).
\]
Because
$\Delta {\nab p}-\nab (\nab\cdot {\nab p})=\Delta {\nab p}- \nab \Delta  p=0$,
we conclude that \eqref{f:nop} holds.
\end{proof}

