\begin{proposition}\label{three:order:pde:propEdit}
Suppose that $\bu=(u^{(1)},u^{(2)})$, ${\bm f}=(f^{(1)},f^{(2)})$, ${\bm g}=(g^{(1)},g^{(2)})$,  $p$, $\phi$ satisfy \eqref{Model:Original}
and	are smooth in the closure of a polygonal domain $\Omega\subset  \R^2$ ($\Omega$ is not necessarily an axis-aligned domain). Let $\Gamma$  be a straight-line segment on the boundary $\partial\Omega$ which can be parametrized as
%
\be \label{parametrized}
x(t)={\textup\ka}_1t+{\textup\ba}_1, \quad y(t)={\textup\ka}_2t+{\textup\ba}_2, \qquad {\textup\ka}_1, {\textup\ka}_2, {\textup\ba}_1, {\textup\ba}_2\in \R, \qquad (x(t),y(t)) \in \Gamma \subset \Omega,
\ee
%
where $|{\textup\ka}_1|+|{\textup\ka}_2|\ne 0$.
Then there holds
\be
	 \begin{split}\label{bd:eqn:1:three:order:Edit} &{\textup\ka}_1^2({\textup\ka}_1-3{\textup\ka}_2)u^{(1)}_{xxx}+{\textup\ka}_1(2{\textup\ka}_1^2+3{\textup\ka}_1{\textup\ka}_2-3{\textup\ka}_2^2)u^{(1)}_{xxy}+	 {\textup\ka}_2^2(3{\textup\ka}_1-{\textup\ka}_2)u^{(1)}_{xyy}+({\textup\ka}_1^3+{\textup\ka}_2^3 )u^{(1)}_{yyy}\\
	&\quad  =3{\textup\ka}_1^2{\textup\ka}_2\phi_{xx}+{\textup\ka}_1(3{\textup\ka}_2^2-{\textup\ka}_1^2)\phi_{xy} +{\textup\ka}_2^3\phi_{yy} +\nu^{-1}{\textup\ka}_1^3( f^{(2)}_{x} - f^{(1)}_{y})+\rho_1+\rho_2 \quad \text{on} \quad \Gamma,
	\end{split}
	\ee
	and
	\be
	 \begin{split}\label{bd:eqn:2:three:order:Edit}
		 &({\textup\ka}_1^3+{\textup\ka}_2^3)u^{(2)}_{xxx}+{\textup\ka}_1^2(3{\textup\ka}_2-{\textup\ka}_1)u^{(2)}_{xxy}+	 {\textup\ka}_2(2{\textup\ka}_2^2+3{\textup\ka}_1{\textup\ka}_2-3{\textup\ka}_1^2)u^{(2)}_{xyy}+{\textup\ka}_2^2({\textup\ka}_2-3{\textup\ka}_1 )u^{(2)}_{yyy}\\
		&\quad  ={\textup\ka}_1^3\phi_{xx}+{\textup\ka}_2(3{\textup\ka}_1^2-{\textup\ka}_2^2)\phi_{xy} +3{\textup\ka}_1{\textup\ka}_2^2 \phi_{yy} +\nu^{-1}{\textup\ka}_2^3( f^{(1)}_{y} -f^{(2)}_{x})  +\rho_1+\rho_2 \quad \text{on} \quad \Gamma,
	\end{split}
	\ee
%
where
\[
\rho_r:=\sum_{i=0}^3{3 \choose i}  {\textup\ka}_1^{3-i}{\textup\ka}_2^{i}\frac{\p^3 g^{(r)}}{\p x^{3-i} \p y^{i}}, \qquad r=1,2.
\]
Furthermore, the right-hand sides of \eqref{bd:eqn:1:three:order:Edit} and \eqref{bd:eqn:2:three:order:Edit} are completely independent of both the pressure $p$ and the constant kinematic viscosity $\nu$ in \eqref{Model:Original} due to
%
\begin{equation}\label{indepen:p:v}
 \nu^{-1} [f^{(1)}_y- f^{(2)}_x]=\Delta [u^{(2)}_{x}-u^{(1)}_{y}].
\end{equation}
\end{proposition}
%
%
%
\begin{proof}
%
We only prove  \eqref{bd:eqn:1:three:order:Edit} and \eqref{indepen:p:v}, as \eqref{bd:eqn:2:three:order:Edit} can be proved similarly.
It follows directly from \eqref{Model:Original} and \eqref{parametrized} that on $\Gamma$, we have
%
%
\begin{align}
	-u^{(1)}_{xxx}-	u^{(2)}_{xxy} &= \phi_{xx},\label{ident:1}\\
	-u^{(1)}_{xxy}-	u^{(2)}_{xyy} &= \phi_{xy},\label{ident:2}\\
	-u^{(1)}_{xyy}-	u^{(2)}_{yyy} &= \phi_{yy},\label{ident:3}\\
	-\nu u^{(2)}_{xxx}	-\nu u^{(2)}_{xyy} + p_{xy} & = f^{(2)}_x,\label{ident:4}\\
	-\nu u^{(1)}_{xxy}	-\nu u^{(1)}_{yyy} + p_{xy} & = f^{(1)}_y,\label{ident:5}\\
u_{ttt}^{(1)}= g_{ttt}^{(1)}\Rightarrow \ka_1^3u^{(1)}_{xxx}+3\ka_1^2\ka_2u^{(1)}_{xxy}+3\ka_1\ka_2^2u^{(1)}_{xyy}+\ka_2^3u^{(1)}_{yyy} & =\rho_1, \label{ident:6}\\
u_{ttt}^{(2)} = g_{ttt}^{(2)} \Rightarrow \ka_1^3u^{(2)}_{xxx}+3\ka_1^2\ka_2u^{(2)}_{xxy}+3\ka_1\ka_2^2u^{(2)}_{xyy}+\ka_2^3u^{(2)}_{yyy} &=\rho_2. \label{ident:7}
\end{align}
%
Then
$ 3\ka_1^2\ka_2 \times \eqref{ident:1}+\ka_1(3\ka_2^2-\ka_1^2)  \times \eqref{ident:2} +\ka_2^3 \times \eqref{ident:3} +\nu^{-1}\ka_1^3 \times (  \eqref{ident:4} - \eqref{ident:5}) +\eqref{ident:6}   + \eqref{ident:7}$ yields
%
%
\begin{align*}
&3{\textup\ka}_1^2{\textup\ka}_2\phi_{xx}+{\textup\ka}_1(3{\textup\ka}_2^2-{\textup\ka}_1^2)\phi_{xy} +{\textup\ka}_2^3\phi_{yy} +\nu^{-1}{\textup\ka}_1^3( f^{(2)}_{x} - f^{(1)}_{y}) + \rho_1+\rho_2\\	
& =3\ka_1^2\ka_2 (	-u^{(1)}_{xxx}-	 u^{(2)}_{xxy})+\ka_1(3\ka_2^2-\ka_1^2)  (-u^{(1)}_{xxy}-	u^{(2)}_{xyy}) +\ka_2^3 (	-u^{(1)}_{xyy}-	 u^{(2)}_{yyy}) \\
&\quad +\nu^{-1}\ka_1^3(  	-\nu u^{(2)}_{xxx}	-\nu u^{(2)}_{xyy}  +\nu u^{(1)}_{xxy}	+\nu u^{(1)}_{yyy} )+\ka_1^3u^{(1)}_{xxx}+3\ka_1^2\ka_2u^{(1)}_{xxy} \\
&\quad+3\ka_1\ka_2^2u^{(1)}_{xyy} +\ka_2^3u^{(1)}_{yyy}+\ka_1^3u^{(2)}_{xxx}+3\ka_1^2\ka_2u^{(2)}_{xxy}+3\ka_1\ka_2^2u^{(2)}_{xyy}+\ka_2^3u^{(2)}_{yyy}\\
& =(\ka_1^3-3\ka_1^2\ka_2)u^{(1)}_{xxx}+(-3\ka_1\ka_2^2+\ka_1^3+\ka_1^3+3\ka_1^2\ka_2)  u^{(1)}_{xxy}+(3\ka_1\ka_2^2-\ka_2^3) u^{(1)}_{xyy}+	(\ka_1^3+\ka_2^3 ) u^{(1)}_{yyy}\\
& \quad + (\ka_1^3-\ka_1^3)u^{(2)}_{xxx}+(3\ka_1^2\ka_2 -3\ka_1^2\ka_2)u^{(2)}_{xxy}+ (-3\ka_1\ka_2^2+\ka_1^3-\ka_1^3+3\ka_1\ka_2^2)  	 u^{(2)}_{xyy} +(\ka_2^3-\ka_2^3) 	 u^{(2)}_{yyy} \\
& =(\ka_1^3-3\ka_1^2\ka_2)u^{(1)}_{xxx}+(2\ka_1^3-3\ka_1\ka_2^2+3\ka_1^2\ka_2)  u^{(1)}_{xxy}+(3\ka_1\ka_2^2-\ka_2^3) u^{(1)}_{xyy}+	(\ka_1^3+\ka_2^3 ) u^{(1)}_{yyy}, \quad \text{on} \quad \Gamma.
\end{align*}
%
So \eqref{bd:eqn:1:three:order:Edit} is proved.

%Note that both the pressure $p$ and $\nu$ only appears in the identity $-\nu \Delta \bu+\nab p={\bm f}$ of \eqref{Model:Original},
%that is,  ${\bm f}$ depends on $\bu$, $p$ and $\bu$, then we trivially have
%$\nu^{-1} f^{(1)}=- \Delta u^{(1)}+\nu^{-1} p_x$ and
%$\nu^{-1} f^{(2)}=- \Delta u^{(2)}+\nu^{-1} p_y$.
Next, using  $-\nu \Delta \bu+\nab p={\bm f}$, we have
%Consequently, 
\[
\nu^{-1}f^{(1)}_y-\nu^{-1} f^{(2)}_x=
[- \Delta u^{(1)}_{y}+\nu^{-1} p_{xy}]-
[- \Delta u^{(2)}_{x}+\nu^{-1} p_{yx}]
=\Delta [u^{(2)}_{x}-u^{(1)}_{y}],
\]
which only depends on $\bu$. This proves \eqref{indepen:p:v}.
\end{proof}

%
If $\p\Omega$ only contains edges parallel to the coordinate axis, i.e.
if $(\ka_1,\ka_2)=(0,1)$ in \eqref{parametrized} for  $x=\text{const}$ and  $(\ka_1,\ka_2)=(1,0)$ in \eqref{parametrized} for  $y=\text{const}$, then \cref{biharmonic:propEdit,three:order:pde:propEdit}
reduce to the following reformulation.

%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{thm:all:pde:2D}
Assume that the boundary of a domain $\Omega$ has a decomposition
$\p\Omega = \big(\cup_{m=1}^{N_x} \overline{\Gamma_m^x}\big)\cup \big(\cup_{n=1}^{N_y} \overline{\Gamma_n^y}\big)$,
where $\Gamma_m^x = \{(\alpha_m,y):\ a^x_m< y<b^x_m\}$ and $\Gamma_n^y = \{(x,\beta_n):\ a^y_n< x< b_n^y\}$
with $\alpha_m,a^x_m, b^x_m, \beta_n, a^y_n, b^y_n \in \bbR$ and $N_x,N_y\in \N$. That is, the variable $x$ is constant on $\Gamma_m^x$, and the variable
$y$ is constant on $\Gamma_n^y$.
Suppose that  $\bu=(u^{(1)},u^{(2)})$,  ${\bm f}=(f^{(1)},f^{(2)})$,  ${\bm g}=(g^{(1)},g^{(2)})$, 	$\phi$ and $p$ satisfy \eqref{Model:Original} and are smooth on $\overline{ \Omega}$.
Then the following PDEs hold
\begin{equation}\label{eqn:FourthOrderPDE}
\left\{
\begin{array}{ll}
 -\Delta^2 u^{(1)} = \psi^{(1)} \qquad &\text{in }\Omega,\\
 u^{(1)} =g^{(1)} \quad &\text{on }\p\Omega,\\
 u^{(1)}_{xyy} = \varphi^{(1)}_1    &\text{on }\Gamma_m^x,\\
u^{(1)}_{yyy}	+2u^{(1)}_{xxy}  =\varphi^{(1)}_2  &\text{on }\Gamma_n^y,
\end{array}\right.
\qquad
\left\{\begin{array}{ll}
- \Delta^2 u^{(2)} = \psi^{(2)} \qquad &\text{in }\Omega,\\
 u^{(2)} =g^{(2)} \quad &\text{on }\p\Omega,\\
 u^{(2)}_{xxx}+ 2u^{(2)}_{xyy} = \varphi^{(2)}_1   &\text{on }\Gamma_m^x,\\
u^{(2)}_{xxy}    =\varphi^{(2)}_2  &\text{on }  \Gamma_n^y,
\end{array}\right.
\end{equation}
for $m=1,\ldots,N_x$ and $n=1,\ldots,N_y$,
%
where $(\psi^{(1)},\psi^{(2)})={\bm \psi}=\Delta (\nab \phi) + \nu^{-1}[ \Delta {\bm f}- \nab (\nab\cdot {\bm f})]$ is defined in \eqref{eqn:BiharmonicEdit}, and
%
		\begin{equation}	 \label{RHS:2d}
		\begin{split}
%		&	{\bm \psi}:=	\Delta (\nab g) +\nu^{-1}\Delta {\bm f}-\nu^{-1}\nab (\nab\cdot {\bm f}),  	 \\
		& \varphi^{(1)}_1:=-\phi_{yy}-g^{(2)}_{yyy},  \qquad \varphi^{(1)}_2:=
-\nu^{-1}[
f^{(1)}_{y}-f^{(2)}_{x}]- \phi_{xy}+g^{(2)}_{xxx},\qquad   \\
		&  \varphi^{(2)}_2:=-\phi_{xx}-g^{(1)}_{xxx}, \qquad \varphi^{(2)}_1:=
\nu^{-1}[f^{(1)}_{y}-  f^{(2)}_{x}]
-  \phi_{xy}+g^{(1)}_{yyy}.
		\end{split}
		\end{equation}	
	%
	Importantly,  the right-hand side functions $\bpsi$ and $\varphi^{(r)}_j$ with $r,j\in \{1,2\}$ are all completely independent of both the pressure $p$ and the constant kinematic viscosity $\nu$ in \eqref{Model:Original} due to
%
\begin{equation}\label{nop:all}
\nu^{-1} [\Delta {\bm f}- \nab (\nab \cdot {\bm f})]=- \Delta^2 \bu+\nab (\nab \cdot \Delta \bu),
\qquad \nu^{-1} [f^{(1)}_y- f^{(2)}_x]=\Delta [u^{(2)}_{x}-u^{(1)}_{y}].
\end{equation}
	%
	%
\end{theorem}
%
%
\begin{proof}
The identities $-\Delta^2 u^{(1)}=\psi^{(1)}$, $-\Delta^2 u^{(2)}=\psi^{(2)}$, and the independence of $\bpsi$ from $p$ follow directly from
\cref{biharmonic:propEdit}.

 \eqref{bd:eqn:1:three:order:Edit} with $(\ka_1,\ka_2)=(0,1)$ and  $(\ka_1,\ka_2)=(1,0)$ results in the third-order PDEs  $u^{(1)}_{xyy} = \varphi^{(1)}_1$  and
 $u^{(1)}_{yyy}	+2u^{(1)}_{xxy}  =\varphi^{(1)}_2$, respectively.  Likewise, \eqref{bd:eqn:2:three:order:Edit} with $(\ka_1,\ka_2)=(0,1)$ and  $(\ka_1,\ka_2)=(1,0)$ results in the third-order PDEs  $ u^{(2)}_{xxx}+ 2u^{(2)}_{xyy} = \varphi^{(2)}_1$  and
 $u^{(2)}_{xxy}    =\varphi^{(2)}_2$, respectively.

The first identity of \eqref{nop:all} has already been proved in \eqref{f:nop}, and the second identity in 
\eqref{nop:all} is a restatement of
\eqref{indepen:p:v}.
 %
\end{proof}	
%
%
%
%
%
\begin{remark}

 Note that, similar to the well-known streamfunction formulation (see, e.g., \cite{Glowinski1979})
		the PDEs \eqref{eqn:BiharmonicEdit} and \eqref{eqn:FourthOrderPDE}
		are fourth-order problems involving the biharmonic operator.
		However these formulations are clearly distinct, as \eqref{eqn:BiharmonicEdit}
		and \eqref{eqn:FourthOrderPDE} are formulated solely in terms of the velocity.
		Furthermore, unlike the streamfunction formulation, we do not require
		the domain $\Omega$ to be simply connected.
\end{remark}

\begin{remark}
After determining the unknown velocity fields $u^{(1)}$ and $u^{(2)}$, we can determine  the gradient of the pressure $p$ through $\nab p={\bm f}+\nu \Delta u$ in \eqref{Model:Original}.
\end{remark}


