\subsection{A sixth-order FD operator for smooth $\bu$ at interior grid points}\label{FDMs:interior}
%
We present a 25-point FD operator with  the sixth-order of consistency at the interior grid point in the following lemma. %\cref{theorem:interior}.
%
\begin{lemma}\label{theorem:interior}
We define the following 25-point FD operator on the set of interior grid points $\Omega_h$:
%
\be\label{FDMs:u:interior}
\mathcal{L}_h (\bu_h)_{i,j} :=\sum_{k,\ell=-2}^2 C_{k,\ell} (\bu_h)_{i+k,j+\ell},
\ee
%
where $C_{0,0}:=-13$,
%
\be
\label{Ckl:interior}
\begin{split}
& C_{-2,-2}=C_{-2,2}=C_{2,-2}=C_{2,2}:=-\tfrac{1}{36}, \qquad C_{-2,0}=C_{2,0}=C_{0,-2}=C_{0,2}:=-\tfrac{1}{2} ,\\
& C_{-2,-1}=C_{-2,1}= C_{2,-1}=C_{2,1}=C_{-1,-2}=C_{-1,2}=C_{1,-2}=C_{1,2}:=-\tfrac{2}{9},\\
& C_{-1,-1}=C_{-1,1}=C_{1,-1}=C_{1,1}:=\tfrac{2}{9}, \qquad  C_{-1,0}=C_{1,0}=C_{0,-1}=C_{0,1}:=4.
\end{split}
\ee	
%
We also set
%
\be\label{bpsi:h}
(\bpsi_h)_{i,j} :=
\left( {\bm\psi}  + \tfrac{h^2}{6} \Delta{\bm\psi}   +h^4\Big(\tfrac1{80} \Delta^2 \bpsi + \tfrac1{90} \tfrac{\p^4 \bpsi}{\p x^2 \p y^2}
\Big)\right)\Big|_{x={\textup\xa}_i,y={\textup\ya}_j}.\\
\ee
%
Then there holds $\left|\left(h^{-4}\mathcal{L}_h (\bu)- \bpsi_h\right)_{i,j}\right|=\bo(h^6)$ at $({\textup\xa}_i,{\textup\ya}_j) \in \Omega_h$ provided  $\bu$ is smooth.
\end{lemma}
%
%
\begin{proof}
Using a Taylor approximation at an interior grid point $(\xa_i,\ya_j)$, we have
%
%
%
\be \label{u:original}
\bu(x_i+x,y_j+y)
=
\sum_{(m,n)\in \ind_{M+1}}
\frac{\partial^{m+n}\bu(\xa_i,\ya_j) }{\partial x^m \partial y^n}\frac{x^my^n}{m!n!}+\bo(h^{M+2}), \qquad x,y\in \{0,\pm h, \pm 2h\},
\ee
%
where
\be \label{ind}
\ind_{M+1}:=\{ (m,n)\in \NN^2 \; : \;  m+n\le M+1 \}, \qquad M+1\in \NN,\qquad \NN:=\N\cup\{0\}.
\ee
%
For the sake of readability, we omit the subscripts and use the following notation in this proof:
%
\[
\frac{\partial^{m+n}\bu }{\partial x^m \partial y^n}:=\frac{\partial^{m+n}\bu(\xa_i,\ya_j) }{\partial x^m \partial y^n}, \qquad \frac{\partial^{m+n} \bpsi}{\partial x^m \partial y^n}:=\frac{\partial^{m+n}\bpsi(\xa_i,\ya_j) }{\partial x^m \partial y^n}.
\]
%We define that
%\be\label{L:h:u:interior}
%	\mathcal{L}_h (u^{(r)})_{i,j} :=\sum_{k=-2}^2\sum_{k=-2}^2 C_{k,\ell} (u^{(r)})_{i+k,j+\ell} =\sum_{k=-2}^2\sum_{k=-2}^2 C_{k,\ell} u^{(r)}(\xa_i+kh,\ya_j+\ell h).
%\ee
%

A calculation shows, using \eqref{FDMs:u:interior}--\eqref{Ckl:interior}  and \eqref{u:original} with $M=8$,
% and $(u^{(r)})_{i+k,j+\ell}=u^{(r)}(\xa_i+kh,\ya_j+\ell h)$
	 \begin{equation}\label{interior:plug:taylor}
	\begin{split}
	\frac1{h^4}\mathcal{L}_h (\bu)_{i,j}
%	&= \frac1{h^4}\sum_{k,\ell=-2}^2 C_{k,\ell }(\bu)_{i+k,j+\ell}\\
	& =-\Big( \tfrac{ \partial^{4}\bu }{\partial x^4} + 2\tfrac{\partial^{4}\bu }{\partial x^2 \partial y^2}  +\tfrac{\partial^{4}\bu }{\partial y^4} \Big)
	- \tfrac{h^2}{6}\Big(  \tfrac{\partial^{6}\bu }{\partial x^6} +3 \tfrac{ \partial^{6}\bu }{\partial x^4 \partial y^2}  + 3\tfrac{\partial^{6}\bu }{\partial x^2 \partial y^4}  +\tfrac{\partial^{6}\bu }{\partial y^6} \Big) 	 \\
	&\quad-h^4\Big(  \tfrac{1}{80}\tfrac{\partial^{8}\bu }{\partial x^8}  +  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^6 \partial y^2} + \tfrac{7}{72}\tfrac{\partial^{8}\bu }{\partial x^4 \partial y^4}+  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^2 \partial y^6}  +\tfrac{1}{80} \tfrac{\partial^{8}\bu }{\partial y^8} \Big) +\bo(h^{6})\\
%
%& = -\Delta^2 \bu - \tfrac{h^2}{6} \Delta^3 \bu\\
%&\quad-h^4\Big(  \tfrac{1}{80}\tfrac{\partial^{8}\bu }{\partial x^8}  +  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^6 \partial y^2} + \tfrac{7}{72}\tfrac{\partial^{8}\bu }{\partial x^4 \partial y^4}+  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^2 \partial y^6}  +\tfrac{1}{80} \tfrac{\partial^{8}\bu }{\partial y^8} \Big) +\bo(h^{6})\\
%
& = \bpsi +\tfrac{h^2}{6} \Delta \bpsi\\
&\quad-h^4\Big(  \tfrac{1}{80}\tfrac{\partial^{8}\bu }{\partial x^8}  +  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^6 \partial y^2} + \tfrac{7}{72}\tfrac{\partial^{8}\bu }{\partial x^4 \partial y^4}+  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^2 \partial y^6}  +\tfrac{1}{80} \tfrac{\partial^{8}\bu }{\partial y^8} \Big) +\bo(h^{6}).
	\end{split}
	\end{equation}
%	
Next, we use a simple calculation and $-\Delta^2 \bu = \bpsi$ to write
\begin{align*}
  &\tfrac{1}{80}\tfrac{\partial^{8}\bu }{\partial x^8}  +  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^6 \partial y^2} + \tfrac{7}{72}\tfrac{\partial^{8}\bu}{\partial x^4 \partial y^4}+  \tfrac{11}{180}\tfrac{\partial^{8}\bu }{\partial x^2 \partial y^6}  +\tfrac{1}{80} \tfrac{\partial^{8}\bu }{\partial y^8}\\
  &\qquad = \tfrac1{80} \Delta^4 \bu + \tfrac1{90} \tfrac{\partial^{8}\bu }{\partial x^6 \partial y^2}
  + \tfrac{1}{45} \tfrac{\partial^{8}\bu}{\partial x^4 \partial y^4}+\tfrac1{90}\tfrac{\partial^{8}\bu }{\partial x^2 \partial y^6}\\
  %
  &\qquad = \tfrac1{80} \Delta^4 \bu+ \tfrac1{90} \tfrac{\partial^4}{\p x^2 \p y^2} \Delta^2 \bu
  %
 = -\tfrac1{80}  \Delta^2 \bpsi - \tfrac1{90} \tfrac{\partial^4}{\p x^2 \p y^2} \bpsi.
\end{align*}
%
Combining this identity with \eqref{interior:plug:taylor} yields
	\begin{align*}
	\frac1{h^4}\mathcal{L}_h (\bu)_{i,j}
	 &=  \bpsi + \tfrac{h^2}{6} \Delta \bpsi + h^4 \left(\tfrac1{80}  \Delta^2 \bpsi + \tfrac1{90} \tfrac{\partial^4}{\p x^2 \p y^2} \bpsi\right)+\bo(h^6)
	 %
	  = (\bpsi_h)_{i,j}+\bo(h^6).
	\end{align*}
This proves the result.
\end{proof}
