	 \frac{\partial^{p+n}\bu(\alpha_m,\ya_j) }{\partial x^p \partial y^n}\frac{x^py^n}{p!n!}+\bo(h^{M+2}),
	\ee
	%
	where  $x\in \{h, 2h,3h\}$ and $y\in \{0,\pm h, \pm 2h\}$ and $\ind_{M+1}$ is defined by \eqref{ind}.
%
Similar to the previous proof, we omit the subscripts for readability
and  use the following notations:
	%
\begin{align*}
%\label{bd:sub:side1}
		\frac{\partial^{p+n}\bu }{\partial x^m \partial y^n}:=\frac{\partial^{p+n}\bu(\alpha_m,\ya_j) }{\partial x^p \partial y^n},\qquad  \frac{\partial^{p+n} {\bm \psi} }{\partial x^p \partial y^n}:=\frac{\partial^{p+n} {\bm \psi}(\alpha_m,\ya_j) }{\partial x^p \partial y^n}, \qquad  \frac{d^n \varphi^{(1)} }{dy^n}:=\frac{d^n \varphi^{(1)}(\alpha_m,\ya_j) }{dy^n}.
\end{align*}


By \eqref{Ckl:1:bd}, \eqref{scheme:u1:side:1},   and \eqref{u:original:bd} with $r=1$ and $M=7$,
%
\begin{align*}
\mathcal{L}_h^{x,1}(u^{(1)})_{i,j}
%		 \sum_{k=0}^2\sum_{\ell=-2}^2 C^{(1)}_{k,\ell }(u^{(1)})_{i+k,j+\ell} =
		&=   \tfrac{11h^2}{6} \tfrac{\partial^{2}u^{(1)} }{\partial y^2}+h^3\tfrac{\partial^{3}u^{(1)} }{\partial x\partial y^2}
		-\tfrac{25h^4}{24} \tfrac{\partial^{4}u^{(1)} }{\partial y^4}-\tfrac{7 h^5}{20} \tfrac{\partial^{5}u^{(1)} }{ \partial x \partial y^4}
		 +h^6\Big(\tfrac1{4}\tfrac{\partial^{6}u^{(1)} }{\partial x^4\partial y^2}\notag \\
		 &\qquad+\tfrac{1}{2}\tfrac{\partial^{6}u^{(1)} }{\partial x^2\partial y^4}-\tfrac{419}{2160}\tfrac{\partial^{6}u^{(1)} }{\partial y^6}\Big)
		 +h^7\Big(\tfrac{3}{10}\tfrac{\partial^{7}u^{(1)} }{\partial x^5\partial y^2}+\tfrac3{5}\tfrac{\partial^{7}u^{(1)} }{\partial x^3\partial y^4}-\tfrac{5}{72}\tfrac{\partial^{7}u^{(1)} }{ \partial x \partial y^6}\Big) \\
		 &\qquad+h^8\Big(\tfrac{5}{24}\tfrac{\partial^{8}u^{(1)} }{\partial x^6\partial y^2}+\tfrac{17}{48}\tfrac{\partial^{8}u^{(1)} }{\partial x^4\partial y^4}
		 +\tfrac{1}{12}\tfrac{\partial^{8}u^{(1)} }{\partial x^2\partial y^6}-\tfrac{359}{24192}\tfrac{\partial^{8}u^{(1)} }{ \partial y^8}\Big)+\bo(h^{9}).\notag
\end{align*}	
%
By \eqref{eqn:FourthOrderPDE},
%\eqref{u1:x1:2d} , \eqref{Dir:bd:2d},
\begin{equation*}
%\label{u:bd:0n}
\tfrac{\partial^n u^{(1)}}{\partial y^n}=0, \qquad n\ge0;\qquad
\tfrac{\partial^{n+1} u^{(1)}}{\partial x\partial y^n}=\tfrac{d^{n-2} \varphi^{(1)}_1}{d y^{n-2}}, \qquad n\ge 2.
\end{equation*}
%
Consequently, there holds	
%	
\begin{align}	 \label{bd:taylor:plug}
%\sum_{k=0}^2\sum_{\ell=-2}^2 C^{(1)}_{k,\ell }(u^{(1)})_{i+k,j+\ell}
\mathcal{L}_h^{x,1}(u^{(1)})_{i,j}
&=  h^3\varphi^{(1)}_1
- \tfrac{7h^5}{20}\tfrac{d^{2}\varphi^{(1)}_1 }{d y^2}+h^6\Big(\tfrac{1}{4}\tfrac{\partial^{6}u^{(1)} }{\partial x^4\partial y^2}
+\tfrac{1}{2} \tfrac{\partial^{6}u^{(1)} }{\partial x^2\partial y^4}\Big) \notag \\
&\quad +h^7\Big(\tfrac{3}{10}\tfrac{\partial^{7}u^{(1)} }{\partial x^5\partial y^2}+\tfrac{3}{5}\tfrac{\partial^{7}u^{(1)} }{\partial x^3\partial y^4}-\tfrac{5}{72}\tfrac{d^{4}\varphi^{(1)}_1 }{d y^4}\Big) \\
&\qquad +h^8\Big(\tfrac{5}{24}\tfrac{\partial^{8}u^{(1)} }{\partial x^6\partial y^2}+\tfrac{17}{48}\tfrac{\partial^{8}u^{(1)} }{\partial x^4\partial y^4}+\tfrac{1}{12}\tfrac{\partial^{8}u^{(1)} }{\partial x^2\partial y^6}\Big)+\bo(h^{9}).\notag
	\end{align}


We then write
\begin{equation}\label{eqn:T1}
\begin{split}
\Big(\tfrac{1}{4}\tfrac{\partial^{6}u^{(1)} }{\partial x^4\partial y^2}
		+\tfrac{1}{2} \tfrac{\partial^{6}u^{(1)} }{\partial x^2\partial y^4}\Big)
		& = \tfrac1{4} \tfrac{\p^2}{\p y^2} \Delta^2 u^{(1)} -\tfrac{1}{4}\tfrac{\p^6 u^{(1)}}{\p y^6} =  -\tfrac1{4} \tfrac{\p^2}{\p y^2}  \psi^{(1)},
\end{split}
\end{equation}
%
and
\begin{equation}\label{eqn:T2}
\begin{split}
\Big(\tfrac{3}{10}\tfrac{\partial^{7}u^{(1)} }{\partial x^5\partial y^2}+\tfrac{3}{5}\tfrac{\partial^{7}u^{(1)} }{\partial x^3\partial y^4}-\tfrac{5}{72}\tfrac{d^{4}\varphi^{(1)}_1 }{ d y^4}\Big)
& = \tfrac{3}{10} \tfrac{\p^3}{\p x \p y^2} \Delta^2 u^{(1)} - \tfrac3{10} \tfrac{\p^7 u^{(1)}}{\p x \p y^6} -\tfrac{5}{72}\tfrac{d^{4}\varphi^{(1)}_1 }{ d y^4}\\
%
& = -\tfrac{3}{10} \tfrac{\p^3}{\p x \p y^2} \psi^{(1)}-\tfrac{133}{360} \tfrac{d^{4}\varphi^{(1)}_1 }{ d y^4}.
\end{split}
\end{equation}

Moreover, a simple calculation shows (recalling $\Delta^2 \bu =-\bpsi$)
\begin{align*}
\tfrac{-5}{24} \tfrac{\p^4 \psi^{(1)}}{\p x^2 \p y^2} + \tfrac1{16} \tfrac{\p^4\psi^{(1)}}{\p y^4} &= \tfrac{5}{24}\tfrac{\p^4}{\p x^2 \p y^2} \Delta^2 u^{(1)}-\tfrac1{16} \tfrac{\p^4}{ \p y^4} \Delta^2 u^{(1)}   \\
& = \tfrac5{24} \tfrac{\p^8 u^{(1)}}{\p x^6 \p y^2} + \tfrac{17}{48}\tfrac{\p^8 u^{(1)}}{\p x^4 \p^4 y} + \tfrac1{12} \tfrac{\p^8 u^{(1)}}{\p x^2\p y^6}- \tfrac1{16} \tfrac{\p^8 u^{(1)}}{\p y^8}.
\end{align*}
%
Consequently,
%
\begin{equation}
\label{eqn:T3}
\begin{split}
\tfrac{5}{24}\tfrac{\partial^{8}u^{(1)} }{\partial x^6\partial y^2}+\tfrac{17}{48}\tfrac{\partial^{8}u^{(1)} }{\partial x^4\partial y^4}+\tfrac{1}{12}\tfrac{\partial^{8}u^{(1)} }{\partial x^2\partial y^6} = \tfrac{-5}{24} \tfrac{\p^4 \psi^{(1)}}{\p x^2 \p y^2} + \tfrac1{16} \tfrac{\p^4\psi^{(1)}}{\p y^4}.
\end{split}
\end{equation}

Plugging in the identities \eqref{eqn:T1}--\eqref{eqn:T3} into \eqref{bd:taylor:plug} yields
		\[
		\begin{split}
\mathcal{L}_h^{x,1}(u^{(1)})_{i,j}
		& =  h^3\varphi^{(1)}_1
		-\tfrac{7 h^5}{20}\tfrac{d^{2}\varphi^{(1)}_1 }{d y^2}-\tfrac{h^6}{4} \tfrac{\p^2 \psi^{(1)}}{\p y^2}-h^7\Big( \tfrac{3}{10} \tfrac{\p^3\psi^{(1)}}{\p x \p y^2}	 +\tfrac{133}{360} \tfrac{d^{4}\varphi^{(1)}_1 }{ d y^4}\Big)\\
		& +h^8\Big(\tfrac{-5}{24} \tfrac{\p^4 \psi^{(1)}}{\p x^2 \p y^2} + \tfrac1{16} \tfrac{\p^4\psi^{(1)}}{\p y^4}\Big)+\bo(h^{9})\\
	& = h^3 \varphi_{1,h}^{(1)} + \bo(h^9),
	\end{split}
	\]
	where we used \eqref{rhos} in the last equality.  We then divide by $h^3$ to obtain
	the desired result.
\end{proof}
