\subsection{Approximating the pressure gradient}\label{sec:pxpy}
%
Using the numerical velocity approximation $\bu_h$ computed by the FDM in Lemmas \ref{theorem:interior}--\ref{theorem:corner:1}, we  introduce a finite difference scheme to approximate the gradient of the pressure $p$. 
Without loss of generality, we assume that  $ a^y_n\le x\le b_n^y$ and  $a^x_m\le y\le b^x_m$ in this subsection.
%
By \eqref{Model:Original}, we have
%
\be\label{pxpy}
p_x  =f^{(1)}+\nu \Delta u^{(1)}, \qquad  \qquad
p_y  =f^{(2)}+\nu \Delta u^{(2)}.
\ee
For any smooth 1D function $a(x)\in C^7(\R)$,
	\begin{align*}
	 a_{xx}(\xa_i)=&\tfrac{1}{h^2}\big[\tfrac{1}{90}a(\xa_{i-3})-\tfrac{3}{20} a(\xa_{i-2})+  \tfrac{3}{2} a(\xa_{i-1})-  \tfrac{49}{18} a(\xa_{i})\\
	&+\tfrac{3}{2}  a(\xa_{i+1})-\tfrac{3}{20}  a(\xa_{i+2})+\tfrac{1}{90} a(\xa_{i+3})\big]+\bo(h^{6}), \qquad \text{if} \qquad a^y_n \le \xa_{i\pm 3} \le b^y_n,\\
	 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	 a_{xx}(\xa_i)=&\tfrac{1}{h^2}\big[ -\tfrac{7}{10} a(\xa_{i\pm7}) +\tfrac{1019}{180}  a(\xa_{i\pm6}) -\tfrac{201}{10}  a(\xa_{i\pm5}) +41  a(\xa_{i\pm4})-  \tfrac{949}{18} a(\xa_{i\pm3})\\
	&+  \tfrac{879}{20} a(\xa_{i\pm2})   	 -\tfrac{223}{10} a(\xa_{i\pm1})+\tfrac{469}{90}a(\xa_{i}) \big]+\bo(h^{6}), \qquad \text{if} \qquad a^y_n \le \xa_{i\pm7} \text{ and } \xa_{i}\le b^y_n, \\
		 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	 a_{xx}(\xa_i)=&\tfrac{1}{h^2}\big[  \tfrac{11}{180} a(\xa_{i\pm6}) -\tfrac{1}{2}  a(\xa_{i\pm5})+\tfrac{9}{5}  a(\xa_{i\pm4})-\tfrac{67}{18}  a(\xa_{i\pm3})+  \tfrac{19}{4} a(\xa_{i\pm2})\\
	&-  \tfrac{27}{10} a(\xa_{i\pm1})-\tfrac{7}{18} a(\xa_{i})+\tfrac{7}{10}a(\xa_{i\mp1})\big]+\bo(h^{6}), \qquad \text{if} \qquad a^y_n \le \xa_{i\pm6} \text{ and } \xa_{i\mp1}\le b^y_n, \\
		 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	 a_{xx}(\xa_i)=&\tfrac{1}{h^2}\big[  -\tfrac{1}{90} a(\xa_{i\pm5})+\tfrac{4}{45}  a(\xa_{i\pm4}) -\tfrac{3}{10}  a(\xa_{i\pm3}) +\tfrac{17}{36}  a(\xa_{i\pm2})+  \tfrac{13}{18} a(\xa_{i\pm1})\\
	& -  \tfrac{21}{10} a(\xa_{i}) +\tfrac{107}{90} a(\xa_{i\mp1}) -\tfrac{11}{180}a(\xa_{i\mp2})\big]+\bo(h^{6}), \qquad \text{if} \qquad a^y_n \le \xa_{i\pm5} \text{ and } \xa_{i\mp2}\le b^y_n.
	\end{align*}
%
%
%
%
%
%
%
%
We can then use the above FD operators to compute $((\bu_{xx})_{h})_{i,j}$
at all grid points $(\xa_i,\ya_j)$. Similarly, we can compute  $((\bu_{yy})_{h})_{i,j}$.
%
%
%
%
%

 By \eqref{pxpy}, we approximate gradient $(p_x,p_y)$ of the pressure $p$ with the sixth-order accuracy   as follows:
	\begin{align*}
	&((p_x)_h)_{i,j}  =f^{(1)}(\xa_i,\ya_j)+\nu ((u^{(1)}_{xx})_{h})_{i,j}+\nu ((u^{(1)}_{yy})_{h})_{i,j}, \\
	&((p_y)_h)_{i,j}  =f^{(2)}(\xa_i,\ya_j)+\nu ((u^{(2)}_{xx})_{h})_{i,j}+\nu ((u^{(2)}_{yy})_{h})_{i,j}.
	\end{align*}



