	\section{Numerical Experiments}\label{numerical:test}
%
%
In this section, we test the FDM for the Stokes problem \eqref{Model:Original},
measuring the error  in the  $\ell_\infty$-norm:
\begin{align*}
& \|\bu_h-\bu\|_{\infty}:=\max\left\{\left\|u_h^{(1)}-u^{(1)}\right\|_{\infty},\left\|u_h^{(2)}-u^{(2)}\right\|_{\infty}\right\},\\
& \|(\nab p)_h-\nab p\|_{\infty}:=\max\left\{\|(p_x)_h-p_x\|_{\infty},\|(p_y)_h-p_y\|_{\infty}\right\}.
\end{align*}
%
%
%
 In addition, we compute $\kappa$, the condition number of the matrix in \eqref{matrix:A1:A2}. We solve $\bu_h=(u^{(1)}_h,u^{(2)}_h)$ together in \cref{example1,example2}, and solve $u^{(1)}_h,u^{(2)}_h$ separately in \cref{example3}.
%
%
%
\begin{example}\label{example1}
	\normalfont
	Consider the square domain $\Omega=(-1,1)^2$, and
	let the functions in \eqref{Model:Original} be given by
	%%%
	\begin{align*}
	 \bu=\left( \cos(3x-3y) \exp(y), \exp(x) \sin(3 x)\cos(3 y) \right ),\qquad p=\sin(x-3y),\qquad \nu=1,10^{-3},10^{-6}.
	\end{align*}
	The functions ${\bm f}, \phi,$ and ${\bm g}$ are then obtained by plugging the above functions into \eqref{Model:Original}.
	The numerical results are presented in Tables \ref{tab:example:1:u}--\ref{tab:example:1:p} and Figures \ref{fig:u:example:1}--\ref{fig:p:example:1}.  From \cref{thm:all:pde:2D,thm:matrix:form}, the viscosity $\nu$  and pressure $p$
	do not appear in the reformulated PDEs  \eqref{eqn:FourthOrderPDE} nor in  the linear system \eqref{matrix:A1:A2} of our proposed sixth-order FDM, i.e.,	our FDM is viscosity- and pressure-robust. In particular,  
	Tables \ref{tab:example:1:u}--\ref{tab:example:1:p} show that the error $\|\bu_h-\bu\|_{\infty}$ is independent of $\nu$ and $p$, and both
	$\|\bu_h-\bu\|_\infty$  and $ \|(\nab p)_h-\nab p\|_{\infty}$ converge with sixth order. Finally,
	we see that the condition number of the linear system  \eqref{matrix:A1:A2} scales like $\bo(h^{-4})$, which is expected since the scheme
	is a discretization of a fourth-order PDE.
\end{example}
