\section{Detailed Proofs of Foundational Theorems}
\label{supp_app:proofs}

\subsection{Theorem: Linearity and Boundedness of Comb Transformation Operator $\mathfrak{C}$}
\begin{theorem}
The Comb Transformation Operator $\mathfrak{C}: \mathcal{A} \rightarrow \mathcal{F}([0,1], \mathcal{A})$, defined by $(\mathfrak{C}A)(t) = (1-t) A_{sys} \oplus t A_{ran}$, is linear. If $\mathcal{A}$ is a Banach space, $A_{sys}, A_{ran}$ are derived from $A$ such that $||A_{sys}||_{\mathcal{A}} \le ||A||_{\mathcal{A}}$ and $||A_{ran}||_{\mathcal{A}} \le ||A||_{\mathcal{A}}$, and $\oplus$ behaves like addition for the purpose of norms (e.g., in a convex combination sense), then $\mathfrak{C}$ is bounded with $||\mathfrak{C}|| \le 1$ and spectral radius $\rho(\mathfrak{C}) = 1$.
\end{theorem}
\begin{proof}
\textbf{Linearity}: Let $A, B \in \mathcal{A}$ and $\alpha, \beta \in \mathbb{R}$ (or $\mathbb{C}$). Assume $(A+B)_{sys} = A_{sys} \oplus B_{sys}$ and $(\alpha A)_{sys} = \alpha A_{sys}$ (and similarly for $ran$).
\begin{align*}
(\mathfrak{C}(\alpha A \oplus \beta B))(t) &= (1-t) (\alpha A \oplus \beta B)_{sys} \oplus t (\alpha A \oplus \beta B)_{ran} \\
&= (1-t) (\alpha A_{sys} \oplus \beta B_{sys}) \oplus t (\alpha A_{ran} \oplus \beta B_{ran}) \\
&= \alpha [(1-t) A_{sys} \oplus t A_{ran}] \oplus \beta [(1-t) B_{sys} \oplus t B_{ran}] \quad \text{(by linearity of } \oplus \text{)} \\
&= \alpha (\mathfrak{C}A)(t) \oplus \beta (\mathfrak{C}B)(t) = (\alpha \mathfrak{C}A \oplus \beta \mathfrak{C}B)(t)
\end{align*}
Thus, $\mathfrak{C}(\alpha A \oplus \beta B) = \alpha \mathfrak{C}A \oplus \beta \mathfrak{C}B$.

\textbf{Boundedness}: The norm in $\mathcal{F}([0,1], \mathcal{A})$ is $||f||_{\mathcal{F}} = \sup_{t \in [0,1]} ||f(t)||_{\mathcal{A}}$.
\begin{align*}
||(\mathfrak{C}A)(t)||_{\mathcal{A}} &= ||(1-t) A_{sys} \oplus t A_{ran}||_{\mathcal{A}} \\
&\le (1-t) ||A_{sys}||_{\mathcal{A}} + t ||A_{ran}||_{\mathcal{A}} \quad \text{(by triangle inequality and properties of } \oplus \text{)} \\
&\le (1-t) ||A||_{\mathcal{A}} + t ||A||_{\mathcal{A}} \quad \text{(by assumption on component norms)} \\
&= ||A||_{\mathcal{A}}
\end{align*}
So, $||\mathfrak{C}A||_{\mathcal{F}} = \sup_{t \in [0,1]} ||(\mathfrak{C}A)(t)||_{\mathcal{A}} \le ||A||_{\mathcal{A}}$. Thus, $||\mathfrak{C}|| \le 1$.

\textbf{Spectral Radius}: Consider a constant algorithm $A_0 \in \mathcal{A}$ such that $(A_0)_{sys} = A_0$ and $(A_0)_{ran} = A_0$. Then $(\mathfrak{C}A_0)(t) = (1-t)A_0 \oplus t A_0 = A_0$. So $A_0$ is an eigenfunction with eigenvalue $\lambda=1$. Thus, the set of eigenvalues is non-empty and $1$ is an eigenvalue. Since $\rho(\mathfrak{C}) = \sup \{|\lambda| : \lambda \text{ is an eigenvalue of } \mathfrak{C}\}$ and for any eigenvalue $\lambda$, $|\lambda| \le ||\mathfrak{C}|| \le 1$, we have $\rho(\mathfrak{C})=1$.
\end{proof}

\subsection{Theorem: Borel-Cantelli Threshold Convergence}
\begin{theorem}[Threshold Convergence (Detailed Sketch)]
Let $\omega_1, \omega_2, \dots, \omega_k$ be i.i.d. samples from the problem space $\Omega$ according to a probability measure $\mu$. Let $R(\omega)$ be a real-valued random variable representing the performance log-ratio (or a similar critical quantity for selection) associated with problem $\omega$. Assume $R(\omega)$ has a continuous cumulative distribution function (CDF) $F_R(x) = P(R(\omega) \le x)$, and let $\theta^*$ be its true population median, i.e., $F_R(\theta^*) = 0.5$. Let $F_{R,k}(x)$ be the empirical CDF based on $k$ samples, and let $\theta_k$ be the empirical median, i.e., a value such that $F_{R,k}(\theta_k) \approx 0.5$.
The Dvoretzky-Kiefer-Wolfowitz (DKW) inequality states that for any $\epsilon > 0$:
$$ P\left( \sup_{x \in \mathbb{R}} |F_{R,k}(x) - F_R(x)| > \epsilon \right) \le 2e^{-2k\epsilon^2} $$
This uniform convergence of empirical CDF to true CDF implies convergence of quantiles. Specifically, for the median, it can be shown that $P(|\theta_k - \theta^*| > \epsilon')$ is also bounded by an exponentially decaying term in $k$ (for any $\epsilon' > 0$, provided $F_R$ is strictly increasing around $\theta^*$, or more generally, under mild conditions on $F_R$). Let this probability be $P_k(\epsilon') \le C_1 e^{-C_2 k (\epsilon')^2}$ for some constants $C_1, C_2$.
The sum $\sum_{k=1}^\infty P_k(\epsilon')$ converges because it is a sum of terms decaying exponentially. By the Borel-Cantelli Lemma, if $\sum P(A_k) < \infty$, then $P(A_k \text{ i.o.}) = 0$. Let $A_k = \{|\theta_k - \theta^*| > \epsilon'\}$. Since $\sum P(A_k) < \infty$, it follows that $P(|\theta_k - \theta^*| > \epsilon' \text{ i.o.}) = 0$. This means that for any $\epsilon' > 0$, the event $|\theta_k - \theta^*| > \epsilon'$ occurs only finitely many times, which is the definition of almost sure convergence: $\theta_k \rightarrow \theta^*$ a.s.
\end{theorem}

\section{Detailed Proofs for Robustness and Theoretical Pillars}
\label{supp_app:proofs_robustness_pillars}

\subsection{P12: Adversarial Algorithm Design (Adaptive Family)}
\begin{theorem}[Adversarial Algorithm Design Robustness]
For any horizon $T$, an adversary may, at each round $t \in [1,T]$, introduce a fresh algorithm whose loss vector $\ell_t \in [0,1]^K$ (for $K$ actions/algorithms available at round $t$) is chosen after observing the learner's past actions. Using Follow-the-Perturbed-Leader (FPL) with i.i.d. Gumbel perturbations of scale 1 added to the cumulative losses, the expected total regret satisfies:
$$ \mathbb{E}[\text{Regret}_T] \le C \sqrt{T \log K_{max}} $$
where $K_{max}$ is the maximum number of algorithms available at any round, and $C$ is a universal constant (e.g., $C \approx 4$).
\end{theorem}
\begin{proof}
\textbf{1. Follow-the-Perturbed-Leader (FPL) Algorithm}: At each round $t$, the learner chooses an action (algorithm) $a_t$ that minimizes the sum of past losses plus a random perturbation:
$$ a_t = \arg\min_{a \in \mathcal{A}_t} \left( \sum_{s=1}^{t-1} \ell_s(a) + p_t(a) \right) $$
where $p_t(a)$ are i.i.d. random variables (e.g., Gumbel(0,1)) drawn freshly for each action $a$ at each round $t$.

\textbf{2. Reduction from Adaptive to Oblivious Adversary}: A key result (e.g., Kalai and Vempala, 2005; related to "be-the-leader" lemmas) shows that the expected regret of FPL against an adaptive adversary is not much worse than its regret against an oblivious adversary (who fixes all loss vectors $\ell_1, \dots, \ell_T$ in advance). Specifically, the regret against an adaptive adversary is bounded by the regret against an oblivious one plus a term that can be small (e.g., $O(1)$ or $O(\sqrt{T})$ depending on the perturbation type and analysis details, often absorbed into constants for $\sqrt{T \log K}$ bounds). For Gumbel perturbations, the analysis often directly yields bounds against adaptive adversaries.

\textbf{3. Regret Bound for FPL against Oblivious Adversary}: For an oblivious adversary and $K$ actions, FPL with suitable random perturbations (like Gumbel or exponential) is known to achieve expected regret bounded by $O(\sqrt{T \log K})$. For instance, with Gumbel perturbations, a common bound is $2\sqrt{T \log K}$ (Hannan consistency argument or analysis via stability).

\textbf{4. Handling Varying Action Sets}: If the set of available algorithms $\mathcal{A}_t$ changes, let $K_{max} = \max_t |\mathcal{A}_t|$. The regret bound typically scales with $K_{max}$. If new algorithms are introduced, the "log $K$" term can sometimes be replaced by "log $T$" if up to $T$ distinct algorithms appear over the horizon.

\textbf{5. Combining Steps}: The FPL algorithm, due to the fresh randomization at each step, effectively "blinds" the adaptive adversary to its future choices. The standard analysis for FPL against oblivious adversaries often carries over with similar rates. The regret bound $\mathbb{E}[\text{Regret}_T] \le C \sqrt{T \log K_{max}}$ is a standard result in online learning for FPL under these conditions. The constant $C$ depends on the range of losses (here $[0,1]$) and the properties of the perturbation. For Gumbel perturbations, $C$ is typically small.
\end{proof}

\subsection{P10: Kernelised AlgoSelect (RKHS Setting)}
\begin{theorem}[Kernelized AlgoSelect Risk Bound]
Let $k(\cdot, \cdot)$ be a universal, bounded kernel with Reproducing Kernel Hilbert Space (RKHS) $\mathcal{H}_K$ (norm $||\cdot||_{\mathcal{H}_K}$). Given data $(x_i, y_i)_{i=1}^n$ where $x_i \in \mathcal{X}$ are problem features and $y_i \in \mathbb{R}$ are performance metrics (e.g., comb parameter $t$ or direct performance). Consider squared loss $\ell(f(x),y) = (f(x)-y)^2$. The kernel ridge regression (KRR) estimator for the seeding function $S(x) \approx f(x)$:
$$ \hat{f} = \arg\min_{f \in \mathcal{H}_K} \left[ \frac{1}{n} \sum_{i=1}^n (f(x_i) - y_i)^2 + \lambda ||f||_{\mathcal{H}_K}^2 \right] $$
If the true optimal seeding function $S^*$ (or its projection onto $\mathcal{H}_K$) has $||S^*||_{\mathcal{H}_K} < \infty$, and we choose $\lambda \asymp 1/\sqrt{n}$, then with probability $\ge 1-\delta$:
$$ \mathbb{E}_{x \sim D_x}[(\hat{f}(x) - S^*(x))^2] \le C \frac{||S^*||_{\mathcal{H}_K}^2}{\sqrt{n}} \log(1/\delta) $$
(assuming $y_i$ are bounded or sub-Gaussian, and $k(x,x) \le K_{bound}^2$). More standard rates are $O(n^{-1/2})$ or $O(n^{-2/3})$ depending on assumptions. A common rate for KRR is $O( (||S^*||_{\mathcal{H}_K}^2 / (\lambda n)) + \lambda ||S^*||_{\mathcal{H}_K}^2 + \text{concentration term})$. With $\lambda = n^{-1/2}$, this gives $O(n^{-1/2})$.
A typical excess risk bound is:
$$ \text{Excess Risk}(\hat{f}) \le C \left( \frac{||S^*||_{\mathcal{H}_K}^2}{\lambda n^2} + \lambda ||S^*||_{\mathcal{H}_K}^2 + \frac{K_{bound}^2 \log(1/\delta)}{\lambda n} \right) $$
Optimizing $\lambda$ (e.g., $\lambda \sim K_{bound}/\sqrt{n}$) yields rates like $O(K_{bound} ||S^*||_{\mathcal{H}_K} / \sqrt{n})$.
If $S^* \in \mathcal{H}_K$, a common result for KRR is that if $\lambda \sim n^{-\alpha}$ where $\alpha \in [1/2, 1]$, the $L_2(D_x)$ error is $O_P(n^{-\beta})$ for some $\beta$ related to $\alpha$ and smoothness of $S^*$. For general consistency, $O_P(n^{-1/2})$ is often achievable under weaker conditions if $\lambda \to 0$ and $\lambda\sqrt{n} \to \infty$.
Let's state a more standard bound:
With $\lambda = n^{-1/2}$, and assuming $S^* \in \mathcal{H}_K$ and $y_i$ are $S^*(x_i) + \text{noise}_i$ with sub-Gaussian noise, then with probability $\ge 1-\delta$:
$$ \mathbb{E}_{x \sim D_x}[(\hat{f}(x) - S^*(x))^2] \le C \left( \frac{||S^*||_{\mathcal{H}_K}^2 + K_{bound}^2 \log(1/\delta)}{\sqrt{n}} \right) $$
\end{theorem}
\begin{proof}
\textbf{1. Representer Theorem}: The solution $\hat{f}$ lies in the span of the kernel functions evaluated at the data points: $\hat{f}(\cdot) = \sum_{i=1}^n \alpha_i k(x_i, \cdot)$.
\textbf{2. Bias-Variance Decomposition}: The expected squared error $\mathbb{E}[(\hat{f}(x) - S^*(x))^2]$ can be decomposed into squared bias and variance terms. For KRR, these terms depend on $\lambda$, $n$, and properties of $S^*$ and the kernel.
\textbf{3. Standard KRR Analysis} (e.g., Chapter 5 of Steinwart \& Christmann, "Support Vector Machines"):
The analysis typically involves bounding the "approximation error" (bias due to regularization and $\mathcal{H}_K$ not containing $S^*$) and "sample error" (variance due to finite data).
Let $L_D(f) = \frac{1}{n}\sum (f(x_i)-y_i)^2 + \lambda ||f||_{\mathcal{H}_K}^2$ be the empirical regularized risk, and $L(f) = \mathbb{E}[(f(x)-y)^2]$ be the true risk.
The KRR estimator $\hat{f}$ minimizes $L_D(f)$. We are interested in $L(\hat{f}) - L(S^*)$.
Standard bounds (e.g., from Shalev-Shwartz \& Ben-David, "Understanding Machine Learning", Chapter 16, or specialized KRR literature) show that if $y = S^*(x) + \eta$ with $\mathbb{E}[\eta|x]=0$ and $\mathbb{E}[\eta^2|x] \le \sigma^2$, and $k(x,x) \le K_{bound}^2$:
The excess risk $L(\hat{f}) - L(S^*)$ can be bounded. A common approach involves:
    a. Bounding $|L_D(\hat{f}) - L(\hat{f})|$ and $|L_D(S^*) - L(S^*)|$ using concentration inequalities (e.g., Bernstein for sums of random variables, leveraging the boundedness of the kernel and thus the functions in balls of $\mathcal{H}_K$). This typically introduces terms like $K_{bound}^2 ||f||_{\mathcal{H}_K} \sqrt{\log(1/\delta)/n}$.
    b. Relating $L_D(\hat{f})$ to $L_D(S^*)$ via $\hat{f} = \arg\min L_D(f)$, so $L_D(\hat{f}) \le L_D(S^*)$.
Combining these steps:
$L(\hat{f}) - L(S^*) \le (L(S^*) - L_D(S^*)) + (L_D(\hat{f}) - L(\hat{f})) + \lambda (||S^*||_{\mathcal{H}_K}^2 - ||\hat{f}||_{\mathcal{H}_K}^2)$.
The first two terms are concentration terms. The term $\lambda (||S^*||_{\mathcal{H}_K}^2 - ||\hat{f}||_{\mathcal{H}_K}^2)$ is often bounded by $\lambda ||S^*||_{\mathcal{H}_K}^2$.
A typical result under suitable conditions (e.g., $S^* \in \mathcal{H}_K$, bounded $y_i$ or sub-Gaussian noise) is that for $\lambda \asymp n^{-1/2}$ (or other optimal choices depending on smoothness of $S^*$), the $L_2(D_x)$ error $\mathbb{E}_{x}[(\hat{f}(x) - S^*(x))^2]$ is $O_P(n^{-r})$ where $r$ depends on the problem's difficulty (e.g., smoothness of $S^*$). For general consistency, if $\lambda \to 0$ and $n\lambda \to \infty$, $\hat{f}$ converges.
The stated bound $C \left( \frac{||S^*||_{\mathcal{H}_K}^2 + K_{bound}^2 \log(1/\delta)}{\sqrt{n}} \right)$ is a simplified representation of such rates, where the $\log(1/\delta)$ comes from high-probability concentration bounds. More precise rates often involve specific assumptions on the decay of eigenvalues of the integral operator associated with $k$.
\end{proof}

\subsection{P9: PAC-Bayes Tightening}
\begin{theorem}[PAC-Bayes Bound for AlgoSelect Seeding Function]
Let $\mathcal{H}$ be a hypothesis class for seeding functions. Let $P$ be a prior distribution over $\mathcal{H}$. Let $Q$ be a data-dependent posterior distribution over $\mathcal{H}$. For any $\delta \in (0,1)$, with probability at least $1-\delta$ over the draw of $n$ i.i.d. samples $Z_n = (z_1, \dots, z_n)$, for all $Q$:
$$ \mathbb{E}_{h \sim Q} [R(h)] \le \mathbb{E}_{h \sim Q} [\hat{R}_n(h)] + C \sqrt{\frac{KL(Q||P) + \log(n/\delta)}{n}} $$
where $R(h)$ is the true risk of $h$, $\hat{R}_n(h)$ is its empirical risk on $Z_n$, and $KL(Q||P)$ is the Kullback-Leibler divergence. If losses are in $[0,1]$, $C$ is a small constant.
This implies that for $h_Q = \mathbb{E}_{h \sim Q}[h]$ (if applicable, e.g. for convex loss and $h$ being parameters), or for $h$ drawn from $Q$:
$$ \text{excess\_risk}(h_Q) \le C' \frac{KL(Q||P) + \log(n/\delta)}{n} \quad \text{(for some versions of PAC-Bayes)}$$
More commonly, for bounded losses in $[0,1]$:
$$ \mathbb{E}_{h \sim Q} [R(h)] \le \inf_{h' \in \mathcal{H}} \hat{R}_n(h') + \text{complexity term} $$
A standard PAC-Bayes theorem (e.g., McAllester's): With probability $\ge 1-\delta$, for all $Q$:
$$ \mathbb{E}_{h \sim Q} [R(h)] \le \mathbb{E}_{h \sim Q} [\hat{R}_n(h)] + \sqrt{\frac{KL(Q||P) + \log(2\sqrt{n}/\delta)}{2n}} $$
If $h_Q$ is the Gibbs posterior $Q(h) \propto P(h) \exp(-\eta \hat{R}_n(h))$, then for an optimal $\eta \approx \sqrt{n/(KL+\log(1/\delta))}$:
$$ R(h_Q) - \min_{h^*} R(h^*) \le C \sqrt{\frac{KL(P_{h^*}||P) + \log(1/\delta)}{n}} $$
where $P_{h^*}$ is a Dirac mass at $h^*$. The term $KL(Q||P)$ effectively replaces $\log|\mathcal{H}|$ or VC dimension terms.
\end{theorem}
\begin{proof}
\textbf{1. Change of Measure Inequality (Donsker-Varadhan or Catoni's version for bounded losses)}:
A key step in PAC-Bayes proofs involves relating the expectation under $Q$ of an exponentiated difference between true and empirical risks to the KL divergence. For any $\lambda > 0$:
$$ \mathbb{E}_{h \sim Q} \left[ e^{\lambda (\mathbb{E}_{z \sim D}[ \ell(h,z)] - \frac{1}{n}\sum \ell(h,z_i)) - \lambda^2 \text{Var}(\ell)/2} \right] \le e^{KL(Q||P)} $$
(This is one form; variations exist. For bounded losses in $[0,1]$, a common starting point is Hoeffding's inequality for a fixed $h$, then integrating w.r.t $Q$).
A more direct path for bounded losses uses an inequality like:
For any $\lambda > 0$, $\mathbb{E}_{Z_n} \left[ \mathbb{E}_{h \sim P} \left[ e^{\lambda (\hat{R}_n(h) - R(h)) - \lambda^2/8n} \right] \right] \le 1$.
Then, by an argument involving a change of measure (often using a specific form of $Q$ like the Gibbs posterior $Q(h) \propto P(h)e^{-\eta \hat{R}_n(h)}$):
$$ \mathbb{E}_{h \sim Q} [R(h)] \le \mathbb{E}_{h \sim Q} [\hat{R}_n(h)] + \frac{KL(Q||P) + \log(1/\delta)}{\eta} + \frac{\eta}{2n} \quad \text{(for losses in [0,1])} $$
\textbf{2. Optimizing $\eta$}: Choosing $\eta = \sqrt{2n(KL(Q||P) + \log(1/\delta))}$ minimizes the bound, yielding:
$$ \mathbb{E}_{h \sim Q} [R(h)] \le \mathbb{E}_{h \sim Q} [\hat{R}_n(h)] + \sqrt{\frac{2(KL(Q||P) + \log(1/\delta))}{n}} $$
\textbf{3. Bounding Empirical Risk}: The term $\mathbb{E}_{h \sim Q} [\hat{R}_n(h)]$ can be related to $\inf_{h' \in \mathcal{H}} \hat{R}_n(h')$ or $\inf_{h' \in \mathcal{H}} R(h')$. If $Q$ is chosen as the Gibbs posterior, $\mathbb{E}_{h \sim Q} [\hat{R}_n(h)]$ is close to $\inf_{h'} \hat{R}_n(h')$.
Then, $\mathbb{E}_{h \sim Q} [R(h)] \le \inf_{h' \in \mathcal{H}} R(h') + \text{error terms}$.
The final excess risk bound for $h_Q$ (e.g., the expected hypothesis under $Q$, if the loss is convex) or for a hypothesis drawn from $Q$ typically takes the form $O(\sqrt{(KL(Q||P) + \log(1/\delta))/n})$.
The specific constant $C$ and the exact form depend on the version of the PAC-Bayes theorem used (e.g., Seeger, McAllester, Catoni). The version stated in the theorem summary is a common representation of these results.
\end{proof}

\subsection{P8: Fairness Across g Groups}
\begin{theorem}[Fair AlgoSelect Across Groups]
Let the population be partitioned into $g$ disjoint groups. AlgoSelect using Median-of-Means ERM on data sampled from the overall population, or with per-group MoM if group membership is known and sufficient samples exist per group, ensures that for every group $i \in \{1, \dots, g\}$, with probability $\ge 1-\delta$:
$$ |\text{Risk}_i(\hat{h}) - \text{Risk}_i(h^*_i)| \le C \sqrt{\frac{\log(|\mathcal{H}|/\delta_g) + \log g}{n_i}} $$
where $\hat{h}$ is the learned seeding function, $h^*_i$ is the optimal seeding function for group $i$, $\text{Risk}_i$ is the risk within group $i$, $n_i$ is the number of samples from group $i$, and $\delta_g = \delta/g$.
If aiming for a single predictor $\hat{h}$ and bounding its maximal group-wise excess risk relative to a common $h^*$:
$$ \max_{i} |\text{Risk}_i(\hat{h}) - \text{Risk}_i(h^*)| \le C \sqrt{\frac{\log(|\mathcal{H}|g/\delta)}{\min_i n_i}} $$
A common fairness goal is to bound $\max_i \text{Risk}_i(\hat{h}) - \min_j \text{Risk}_j(\hat{h})$.
The statement from the summary table was: $\max_{1 \le i \le g} |\text{Risk}_i(\hat{h}) - \text{Risk}_i(h^*)| \le C \sqrt{\frac{g\log g + \log(1/\delta)}{n_{total}}}$ (assuming $n_i \approx n_{total}/g$).
\end{theorem}
\begin{proof}
\textbf{1. Per-Group Concentration}: For each group $i$, if we apply MoM-ERM using only data from that group (assuming $n_i$ samples), Theorem T8 gives that with probability $\ge 1-\delta_g$:
$$ |\text{Risk}_i(\hat{h}_i) - \text{Risk}_i(h^*_i)| \le C \sqrt{\frac{\log(|\mathcal{H}|/\delta_g)}{n_i}} $$
where $\hat{h}_i$ is learned only on group $i$'s data.
\textbf{2. Union Bound}: To ensure this holds simultaneously for all $g$ groups with overall probability $\ge 1-\delta$, we set $\delta_g = \delta/g$. The $\log(1/\delta_g)$ term becomes $\log(g/\delta) = \log g + \log(1/\delta)$.
So, for each group $i$, with probability $\ge 1-\delta$:
$$ |\text{Risk}_i(\hat{h}_i) - \text{Risk}_i(h^*_i)| \le C \sqrt{\frac{\log(|\mathcal{H}|) + \log g + \log(1/\delta)}{n_i}} $$
\textbf{3. Single Predictor $\hat{h}$}: If a single predictor $\hat{h}$ is learned on the combined dataset of size $n_{total}$, its performance on group $i$ (with $n_i$ samples from that group contributing to $n_{total}$) can be analyzed. The term $\log(|\mathcal{H}|g/\delta)$ arises from a union bound over hypotheses and groups. The effective sample size for group $i$'s risk estimation is $n_i$. If $n_i \approx n_{total}/g$, then the denominator becomes $n_{total}/g$.
The term $g \log g$ in the numerator of the summary table's bound, $C \sqrt{\frac{g\log g + \log(1/\delta)}{n_{total}}}$, likely arises from specific analyses of uniform convergence over groups or from certain fairness-regularized objectives, where the complexity term scales with $g$. For a simple max over per-group excess risks (each $n_i \approx n/g$), the bound is closer to $C \sqrt{\frac{(\log|\mathcal{H}| + \log g + \log(1/\delta))g}{n_{total}}}$.
The exact form depends on the precise fairness notion and learning algorithm. The core idea is that ensuring fairness or uniform good performance across $g$ groups introduces a dependency on $g$ in the sample complexity, often $\sqrt{g}$ or $\sqrt{\log g}$.
\end{proof}

\subsection{P7: Cascading / Cost-Aware Selection}
\begin{theorem}[Cost-Aware Cascading AlgoSelect]
Consider a set of algorithms $\mathcal{A}_N = \{A_1, \dots, A_N\}$ with known execution costs $c_1 \le c_2 \le \dots \le c_N$ and unknown mean losses (errors) $\mu_1, \dots, \mu_N \in [0,1]$. A cost-aware UCB-like strategy for cascading selection (try cheaper algorithms first, stop if confidence in its loss is low enough compared to cost of trying next) achieves total expected cost-plus-error regret over $T$ rounds:
$$ \mathbb{E}[\text{TotalRegret}_T] = \mathbb{E}\left[\sum_{t=1}^T (\ell(A_{sel}^{(t)}) + \text{Cost}(A_{sel}^{(t)}))\right] - T \cdot \min_{j} (\mu_j + c_j) \le C \sqrt{NT \log T} $$
where $A_{sel}^{(t)}$ is the algorithm ultimately selected and run at round $t$, and $C$ is a constant.
\end{theorem}
\begin{proof}
\textbf{1. Algorithm Idea (Racing UCB with Costs)}: At each round $t$:
    a. For each algorithm $A_j$ not yet eliminated, maintain an empirical mean loss $\hat{\mu}_j(t)$ and a UCB-style confidence bound $U_j(t) = \hat{\mu}_j(t) + \beta_j(t)$, where $\beta_j(t) \propto \sqrt{\log T / N_j(t)}$ and $N_j(t)$ is number of times $A_j$ has been (partially) evaluated.
    b. Consider algorithms in increasing order of cost $c_j$.
    c. For current $A_j$: if $U_j(t) + c_j < \min_{k>j} (\hat{\mu}_k(t) - \beta_k(t) + c_k)$ (optimistic estimate for $A_j$ is better than pessimistic estimate for any more expensive algorithm), select $A_j$.
    d. Otherwise, "eliminate" $A_j$ for this round and consider $A_{j+1}$. This is a simplification; more complex strategies exist (e.g., LUCB, Hoeffding races adapted for costs).

A simpler model is a multi-armed bandit where arm $j$ has reward $-( \ell_j + \lambda c_j)$, where $\lambda$ is a trade-off parameter. Standard UCB gives $\sqrt{NT \log T}$ regret for this modified reward. The challenge is that $c_j$ is paid to observe $\ell_j$.

\textbf{2. Regret Decomposition (Streeter \& Golovin "Online Cost-Sensitive Classification")}:
The regret can often be decomposed into "accuracy regret" and "cost regret".
    a. \textbf{Accuracy Regret}: The regret from picking a sub-optimal algorithm if costs were zero. This is bounded by standard bandit results, e.g., $O(\sqrt{NT \log T})$.
    b. \textbf{Cost Overhead}: The extra cost incurred by trying algorithms that are more expensive than the optimal one, or by trying cheap but bad algorithms too many times.
Analysis of algorithms like "Algorithm::Racing" or cost-sensitive UCB variants (e.g., where the UCB index includes a cost term $I_a(t) = \hat{\mu}_a(t) - \beta_a(t) - \lambda c_a$) shows that the number of times a sub-optimal arm (in terms of cost-sensitive value) is pulled is limited.
Each pull of a sub-optimal arm $A_j$ (where "optimality" is defined by $\mu_j^* + c_j$) contributes to regret. The number of pulls of such an arm is typically bounded by $O(\log T / \Delta_j^2)$, where $\Delta_j$ is the sub-optimality gap. Summing over arms gives the $\sqrt{NT \log T}$ bound.
The constant $C$ depends on the range of losses and costs, and the specific UCB variant.
\end{proof}

\subsection{P4: Infinite Algorithm Family (Metric Entropy)}
\begin{theorem}[AlgoSelect for Infinite Algorithm Families]
Let $\mathcal{H}$ be a (potentially infinite) class of seeding functions, equipped with a pseudo-metric $d(h, h')$ (e.g., $L_2(P_X)$ distance between $h(X)$ and $h'(X)$). Let $N(\tau, \mathcal{H}, d)$ be the $\tau$-covering number of $\mathcal{H}$ with respect to $d$. If AlgoSelect uses Median-of-Means ERM over $\mathcal{H}$ with bounded losses $\ell \in [0,1]$, then with probability $\ge 1-\delta$:
$$ \text{excess\_risk}(\hat{h}) \le C_1 \inf_{h \in \mathcal{H}} (\text{Risk}(h) - \text{Risk}(h^*)) + C_2 \int_{0}^{\text{diam}(\mathcal{H}) } \sqrt{\frac{\log N(\tau, \mathcal{H}, d)}{n}} d\tau + C_3 \sqrt{\frac{\log(1/\delta)}{n}} $$
where $h^*$ is the true optimal seeding function (possibly outside $\mathcal{H}$), and $C_1, C_2, C_3$ are universal constants. The integral term is Dudley's entropy integral.
\end{theorem}
\begin{proof}
\textbf{1. Symmetrization and Rademacher Complexity}: The excess risk is typically bounded using Rademacher complexity $\mathfrak{R}_n(\mathcal{L} \circ \mathcal{H})$ where $\mathcal{L}$ is the loss class.
$$ \mathbb{E}[\sup_{h \in \mathcal{H}} (R(h) - \hat{R}_n(h))] \le 2 \mathbb{E}[\mathfrak{R}_n(\mathcal{L} \circ \mathcal{H})] $$
\textbf{2. Dudley's Entropy Integral Bound}: Rademacher complexity can be bounded by Dudley's integral:
$$ \mathfrak{R}_n(\mathcal{L} \circ \mathcal{H}) \le \frac{C'}{\sqrt{n}} \int_0^{\text{diam}(\mathcal{L} \circ \mathcal{H})} \sqrt{\log N(\tau, \mathcal{L} \circ \mathcal{H}, L_2(P_n))} d\tau $$
Assuming the loss is $L_\ell$-Lipschitz, $\log N(\tau, \mathcal{L} \circ \mathcal{H}, L_2(P_n)) \approx \log N(\tau/L_\ell, \mathcal{H}, L_2(P_n))$.
\textbf{3. Concentration}: The supremum deviation $\sup_{h \in \mathcal{H}} (R(h) - \hat{R}_n(h))$ concentrates around its expectation (e.g., via bounded differences inequality or Talagrand's inequality), adding a $\sqrt{\log(1/\delta)/n}$ term for high probability bounds.
\textbf{4. Median-of-Means Adaptation}: The MoM estimator's analysis can be extended to infinite classes. The core idea is that for a fixed $\tau$-net $\mathcal{H}_\tau$ of $\mathcal{H}$, a union bound over $\mathcal{H}_\tau$ gives concentration for all net points. Then, for any $h \in \mathcal{H}$, find $h_\tau \in \mathcal{H}_\tau$ with $d(h,h_\tau) \le \tau$.
$|R(h) - \hat{R}_n(h)| \le |R(h) - R(h_\tau)| + |R(h_\tau) - \hat{R}_n(h_\tau)| + |\hat{R}_n(h_\tau) - \hat{R}_n(h)|$.
The middle term is controlled by MoM on the net. The first and third terms are controlled by $\tau$ (Lipschitzness of risk and empirical risk). Integrating $\tau$ via the peeling device or chaining argument yields Dudley's integral.
The final bound combines the approximation error (if $h^* \notin \mathcal{H}$) with the complexity term derived from the entropy integral and the high-probability term.
\end{proof}

\subsection{P3: Active-Learning Label Complexity}
\begin{theorem}[Active AlgoSelect Label Complexity]
Consider selecting between two algorithms $A_0, A_1$ based on a 1D feature $x \in [0,1]$. Assume their performance difference $f(x) = \text{Perf}(A_1, x) - \text{Perf}(A_0, x)$ is $L$-Lipschitz, and we want to find $x^*$ where $f(x^*)=0$ (the decision boundary) up to $\epsilon$-accuracy. An active learning strategy (e.g., disagreement-based querying or hierarchical partitioning) that queries noisy labels $y_i = f(x_i) + \eta_i$ (where $\eta_i$ is bounded noise) requires $O(\frac{L}{\epsilon}\log(\frac{L}{\epsilon\delta}))$ labels to find an $\epsilon$-optimal $x^*$ with probability $\ge 1-\delta$. If $f(x)$ has a margin condition (e.g., $|f(x)| \ge M|x-x^*|$ near $x^*$), rates like $O(\log(1/\epsilon))$ are possible.
For general classification with a decision boundary, if the hypothesis class $\mathcal{H}$ has disagreement coefficient $\theta_D < \infty$, active learning can achieve label complexity $O(\theta_D \cdot \text{VCdim}(\mathcal{H}) \log(1/\epsilon))$.
The $O(\log(1/\epsilon)/\epsilon)$ rate mentioned in the summary is typical for certain 1D search or specific active learning settings (e.g., robust binary search under noise).
\end{theorem}
\begin{proof}
(Focusing on a 1D search for $f(x^*)=0$, $L$-Lipschitz $f$, bounded noise $|\eta_i| \le B_N$)
\textbf{1. Algorithm Idea (Robust Binary Search / Hierarchical Partitioning)}:
    a. Maintain an interval $[a,b]$ known to contain $x^*$. Initially $[0,1]$.
    b. Query $f$ at points $x_q = (a+b)/2$. Obtain $y_q = f(x_q) + \eta_q$.
    c. Based on $y_q$ (and possibly other queries near $x_q$ to reduce noise impact), decide if $x^*$ is likely in $[a, x_q]$ or $[x_q, b]$. For example, if $y_q > B_N$, then $f(x_q) > 0$, so $x^*$ is likely in $[a, x_q]$ (if $f$ is decreasing).
\textbf{2. Noise Reduction}: To handle noise, one might query multiple times at/near $x_q$ and average, or use confidence bounds.
\textbf{3. Interval Halving}: Each "successful" step reduces the interval of uncertainty by a factor (e.g., half). To reach $\epsilon$ precision from an initial interval of size $I_0$, we need $O(\log(I_0/\epsilon))$ successful steps.
\textbf{4. Impact of Noise and Lipschitzness}: With noise, determining the sign of $f(x_q)$ requires $f(x_q)$ to be sufficiently far from 0 (i.e., $|f(x_q)| > B_N$). If $f(x_q)$ is small, many samples might be needed at $x_q$ to determine its sign reliably.
The $L$-Lipschitz property means $|f(x) - f(y)| \le L|x-y|$. This relates uncertainty in $f$ to uncertainty in $x$.
\textbf{5. Standard Active Learning Results (e.g., Hanneke's disagreement coefficient)}:
For a more general approach, consider CAL (Cohn, Atlas, Ladner) or query-by-committee.
A common result in active learning for classification is that if we can find a hypothesis $h$ that is $\epsilon$-close to $h^*$ (the true boundary), the number of labels needed is often related to $O(\frac{1}{\epsilon})$ in difficult cases, but can be $O(\log \frac{1}{\epsilon})$ if there's a good margin or low disagreement coefficient.
The $O(\frac{\log(1/\epsilon)}{\epsilon})$ rate often appears in scenarios where the learner needs to estimate values up to $\epsilon$ precision, and each query gives information that reduces variance or uncertainty. For example, in bandit settings with certain structures, or estimating means.
The specific proof for $O(\frac{L}{\epsilon}\log(\frac{L}{\epsilon\delta}))$ for 1D search with Lipschitz functions and noise involves careful construction of confidence intervals and showing that queries are made in regions that maximally reduce the uncertainty about $x^*$. The $\log$ factor comes from the number of interval-halving like steps, and the $1/\epsilon$ factor comes from needing to resolve uncertainty down to $\epsilon$ in the presence of noise and Lipschitzness.
\end{proof}

\subsection{P2: Online to Batch Conversion}
\begin{theorem}[Online-to-Batch Conversion]
Let $\mathcal{A}_{online}$ be an online learning algorithm that, over $T$ rounds, interacts with loss functions $\ell_1, \dots, \ell_T \in [0,1]$ (chosen by an adversary or i.i.d.), producing hypotheses $h_1, \dots, h_T$. Let its total regret be $R_T = \sum_{t=1}^T \ell_t(h_t) - \min_{h^* \in \mathcal{H}} \sum_{t=1}^T \ell_t(h^*)$.
We can construct a batch learning algorithm $\mathcal{A}_{batch}$ as follows: Run $\mathcal{A}_{online}$ on $n$ i.i.d. samples $z_1, \dots, z_n$ (treating each sample as a round). Output $\bar{h} = h_\tau$ where $\tau$ is chosen uniformly from $\{1, \dots, n\}$.
Then, the expected excess risk of $\bar{h}$ is:
$$ \mathbb{E}_{Z_n, \tau}[\text{Risk}(\bar{h})] - \min_{h^* \in \mathcal{H}} \text{Risk}(h^*) \le \frac{\mathbb{E}_{Z_n}[R_n]}{n} $$
With high probability (e.g., via Azuma-Hoeffding on the regret sequence if losses are i.i.d.), if $R_n/n \to 0$:
$$ \text{Risk}(\bar{h}) - \min_{h^* \in \mathcal{H}} \text{Risk}(h^*) \le O\left(\sqrt{\frac{\mathbb{E}[R_n]/n + \log(1/\delta)}{n}}\right) $$
A more common version (Cesa-Bianchi et al.): If $R_T \le G\sqrt{T}$ for some $G$, then $\mathbb{E}[\text{Risk}(\bar{h})] - \min \text{Risk}(h^*) \le G/\sqrt{n}$.
\end{theorem}
\begin{proof}
\textbf{1. Expected Risk of $\bar{h}$}: Let $z_1, \dots, z_n$ be the i.i.d. training samples. $\mathcal{A}_{online}$ generates $h_1, \dots, h_n$.
$$ \mathbb{E}_{\tau}[\text{Risk}(\bar{h})] = \mathbb{E}_{\tau}[\mathbb{E}_{z \sim D}[\ell(h_\tau, z)]] = \frac{1}{n} \sum_{t=1}^n \mathbb{E}_{z \sim D}[\ell(h_t, z)] = \frac{1}{n} \sum_{t=1}^n \text{Risk}(h_t) $$
\textbf{2. Relating to Online Losses}:
$$ \mathbb{E}_{Z_n, \tau}[\text{Risk}(\bar{h})] = \mathbb{E}_{Z_n}\left[\frac{1}{n} \sum_{t=1}^n \text{Risk}(h_t)\right] $$
Since $z_t$ are i.i.d from $D$, $\mathbb{E}_{Z_n}[\ell_t(h_t)] = \mathbb{E}_{Z_n}[\text{Risk}(h_t)]$ if $h_t$ were fixed before $z_t$. However, $h_t$ depends on $z_1, \dots, z_{t-1}$.
Consider the average true risk and average empirical risk:
$$ \mathbb{E}_{Z_n}\left[\frac{1}{n} \sum_{t=1}^n \text{Risk}(h_t)\right] \quad \text{vs} \quad \mathbb{E}_{Z_n}\left[\frac{1}{n} \sum_{t=1}^n \ell_t(h_t)\right] $$
These are related by standard online learning stability arguments or by direct expectation.
The key step from Cesa-Bianchi \& Lugosi (Theorem 2.2):
$$ \mathbb{E}_{Z_n, \tau}[\text{Risk}(\bar{h})] = \mathbb{E}_{Z_n} \left[ \frac{1}{n} \sum_{t=1}^n \ell_t(h_t) \right] $$
This holds because $\mathbb{E}_{z_t}[\ell_t(h_t) | h_t] = \text{Risk}(h_t)$, and $h_t$ is determined by $z_1, \dots, z_{t-1}$.
\textbf{3. Using Regret Definition}:
$$ \frac{1}{n} \sum_{t=1}^n \ell_t(h_t) = \frac{R_n}{n} + \frac{1}{n} \min_{h^* \in \mathcal{H}} \sum_{t=1}^n \ell_t(h^*) $$
Taking expectation $\mathbb{E}_{Z_n}[\cdot]$:
$$ \mathbb{E}_{Z_n, \tau}[\text{Risk}(\bar{h})] = \frac{\mathbb{E}_{Z_n}[R_n]}{n} + \mathbb{E}_{Z_n}\left[\frac{1}{n} \sum_{t=1}^n \ell_t(h^*_{\text{opt\_on\_avg}})\right] $$
where $h^*_{\text{opt\_on\_avg}}$ is the single best hypothesis for the average of empirical losses.
More directly:
$$ \mathbb{E}_{Z_n, \tau}[\text{Risk}(\bar{h})] = \mathbb{E}_{Z_n}\left[\frac{1}{n}\sum_{t=1}^n \ell_t(h_t)\right] \le \mathbb{E}_{Z_n}\left[\frac{1}{n}\sum_{t=1}^n \ell_t(h^*)\right] + \frac{\mathbb{E}_{Z_n}[R_n]}{n} $$
for any fixed $h^* \in \mathcal{H}$. Since $\ell_t(h^*)$ are i.i.d for a fixed $h^*$, $\mathbb{E}_{Z_n}[\frac{1}{n}\sum \ell_t(h^*)] = \text{Risk}(h^*)$.
So, $\mathbb{E}_{Z_n, \tau}[\text{Risk}(\bar{h})] \le \min_{h^* \in \mathcal{H}} \text{Risk}(h^*) + \frac{\mathbb{E}_{Z_n}[R_n]}{n}$.
This gives the expected excess risk bound. High probability bounds can be derived using concentration on $R_n$ if it's a sum of (near) independent terms or by applying Azuma-Hoeffding to the sequence $M_k = \sum_{t=1}^k (\ell_t(h_t) - \text{Risk}(h_t))$.
\end{proof}

