\noindent
where $$\dot{\omega}_{px} = \Ddot{\theta}_2s\theta_1+\dot{\theta}_1\dot{\theta}_2c\theta_1,\ \dot{\omega}_{py} = -\Ddot{\theta}_1,\ 
