\subsection{FDE via $\VECKstar$}

Building on the RS-based approach, our second implementation improves efficiency by using a two-layer encryption strategy. Instead of applying expensive exponential ElGamal encryption directly to all symbols, we encrypt only a small pseudorandom subset. The entire extended RS-encoded file is protected with a lightweight masking method derived from a fast, hash-based stream cipher. A heavyweight (but constant-time) zk-SNARK then succinctly proves consistency between the masked data and the sampled, publicly encrypted symbols.

This second protocol significantly reduces computational complexity, communication overhead, and decoding latency. Since most symbols rely on symmetric-key masking rather than public-key encryption, decryption and verification approach near-plaintext efficiency, making FDE practical even for large, gigabyte-scale data transfers.


In the protocol, $H:\{0,1\}^\ast \!\to\! \mathbb{F}_{p}$ denotes a
cryptographic hash function modeled as a random oracle;
all additions involving $H$ are taken modulo $p$.
We note that $\VECKstar$ inherently requires a much shorter common reference string ($\mathsf{crs}$), since it needs parameters only for the sampled subset $S_R$, whose size is typically much smaller than $n$. However, for consistency and clarity of presentation, we retain the same $\mathsf{crs}$ length across all implementations

\clearpage
\textbf{Case $S=[\ell]$.} 
This corresponds to the scenario where the client requests the entire data set. The alternative scenario, in which $S\subset[\ell]$, can be handled similarly to the procedure outlined earlier for $\VECKplus$.  







\paragraph{$\mathsf{\VECKstar}$:}
\begin{itemize}
    \item $\mathsf{\VECKstar.GEN(crs)}\rightarrow \mathsf{pp}$: 
    On input $\mathsf{crs} = \bigl(\mathcal{G},\{g_1^{\tau_i}\}_{i=1}^{n},\{g_2^{\tau_i}\}_{i=1}^{n}\bigr)$, generate random group elements with unknown discrete logarithms $h \gets_R G_1$ and $h_i \gets_R G_1$  for $i \in [m]\cup\{-1\}$, where $m = \lceil \beta\cdot \ell\rceil$.


    \item[] 
    \item $\mathsf{\VECKstar.Enc(F_{[\ell]}, C_\phi, \phi(X)})
        \rightarrow \mathsf{(vk, sk, ct, \pi)}$.
    \begin{enumerate}
        \item Sample $s \gets_{R} \mathbb{F}_p$, set $\mathsf{sk} := s$, $\mathsf{vk} := h^s$.

        \item Compute $\mathsf{ct}=\{\mathsf{ct}_i\coloneqq \phi(i)+H(\mathsf{sk}, i)\}_{i\in [m]}$.




        \item Generate the Fiat–Shamir challenge
          \[
            S_R \;=\;
            \mathsf{DeriveSubset}\!\bigl(
              H\bigl(C_\phi,\,\mathsf{vk},\,\mathsf{ct}\bigr),
              m,\;|S_R|\bigr),
          \]
          where $|S_R|=\min\!\bigl(\ell+1,\lceil\lambda/(\beta-1)\rceil\bigr)$.



        \item Compute 
        $(\text{--},\,\text{--},\,\mathsf{ct}',\,\pi_R)
        \;\coloneqq\;
        \mathsf{VECK_{El}.Enc}\bigl(F_{S_R},\,C_\phi,\,\phi(X)\bigr)$ --- ignore the $(\mathsf{vk},\mathsf{sk})$ returned by \texttt{VECK\_El.Enc}

        \item Compute a zk-SNARK proof $\pi_Z$ for the relation $\mathcal{R}$:
        \[
            \mathcal{R} \;=\;
            \left\{
            \begin{array}{l}
            \bigl(\mathsf{vk},\,h,\,\{h_i\}_{i\in S_R},\,\\
            \{\mathsf{ct}_i\}_{i\in S_R},\,\{\mathsf{ct}'_i\}_{i\in S_R}\bigr),\\
            \bigl(\mathsf{sk},\,\{x_i\}_{i\in S_R}\bigr)
            \end{array}
            \;\middle|\;
            \begin{array}{l}
            \mathsf{vk} = h^{\mathsf{sk}},\\[4pt]
            \forall i\in S_R:\; \mathsf{ct}_i   = x_i + H(\mathsf{sk},i),\\[4pt]
            \forall i\in S_R:\; \mathsf{ct}'_i = h_i^{\,\mathsf{sk}}\,g_1^{x_i}
            \end{array}
            \right\}.
        \]



        \item Output $\mathsf{(vk, sk, ct, \pi=
        \mathsf{(\pi_Z, \pi_R, ct')}})$        
    \end{enumerate}  


    \item[]
    \item $\mathsf{\VECKstar.Ver_{ct}(F_{[\ell]}, C_\phi, vk, ct, \pi)} \rightarrow 0/1$
    \begin{enumerate}
        \item Parse $\pi$ as $(\pi_Z, \pi_R,  \mathsf{ct'})$.
        \item Compute $b_1 \coloneqq \mathsf{VECK_{El}.Ver_{ct}(F_{S_R}, C_\phi, vk, ct', \pi_R)}$.
        \item Compute $b_2\coloneqq \mathsf{Snark.Ver}(\pi_Z)$.
        \item Output $b_1\wedge b_2$.
    \end{enumerate}

    \item[]
    \item $\mathsf{\VECKstar.Ver_{key} (vk,sk)} 
    \rightarrow 0/1:$ For $\mathsf{sk}=s\in \mathbb{F}_p$, return 1 iff $\mathsf{vk}=h^s$.

    \item[]
    \item $\mathsf{\VECKstar.Dec}(F_{[\ell]}, sk, ct)\rightarrow \{\phi(i)\}_{i\in[\ell]}$
    \begin{enumerate}
        \item Compute the unmasked evaluations $\{\tilde{\phi}(i)\coloneqq \mathsf{ct}_i - H(\mathsf{sk}, i)\}_{i\in [m]}$.
        \item If $\mathsf{RS.Det}([m],\{\tilde{\phi}(i)\}_{i\in[m]}) = 0$ (no error detected), then output $\{\tilde{\phi}(i)\}_{i\in[\ell]}$. Otherwise, run the decoding algorithm and output
        \[
        \mathsf{RS.Dec}\left([\ell], [m], \{\tilde{\phi}(i)\}_{i\in[m]}\right).
        \]
    \end{enumerate}


\end{itemize}

\begin{theorem}
    For the case $S=[\ell]$, the generation and verification times of $\VECKstar$ are $\mathcal{O}(\lambda)$.
\end{theorem}
