\begin{algorithm}[t]
\caption{Bisection to $\varepsilon$ ball of $\partial S$ boundary}
\label{alg:bisection}
\begin{algorithmic}[1]
\Function{Bisect}{$\overline{x}^{in}_{0}, \overline{x}^{out}_{0}, \varepsilon$}
    \State \label{algline:init-out}
    $\overline{x}^{in} \gets \overline{x}^{in}_{0}; 
    \quad 
     \overline{x}^{out} \gets \overline{x}^{out}_{0}$

    \While{\label{algline:while}
    $\| \overline{x}^{in}_{end} - \overline{x}^{out}_{end}\|\geq \varepsilon$}
        \State \label{algline:testpoint}
        $x_\text{test} 
        \gets
        (\overline{x}^{in}_{end} + \overline{x}^{out}_{end})/2$

        \If{$f(x_\text{test}) = 0$}    \Comment{Exterior test point}
            \label{algline:feascheck}

            \State Append $x_{\text{test}}$ to $\overline{x}^{out}$
            \label{algline:assign-out}

        \Else    \Comment{Interior test point}
            \State Append $x_{\text{test}}$ to $\overline{x}^{in}$
            \label{algline:assign-in}

        \EndIf
    \EndWhile

    \State \Return $\overline{x}^{in}, \overline{x}^{out}$
    \label{algline:return}
\EndFunction
\end{algorithmic}
\end{algorithm}




\begin{algorithm}[b]
\caption{Decision Boundary Walk}
\label{alg:decisionStepping}
\begin{algorithmic}[1]
\Function{DecisionBoundary}{$\overline{x}^{in}, \overline{x}^{out}, \partial \mathcal{X}, \varepsilon$}
    \State $\partial \tilde{S}^1 \gets \overline{x}^{in}_{end}$;
        \quad 
        $\partial \tilde{S}^0 \gets \overline{x}^{out}_{end}$
\Repeat
    \State \label{alg:circleIntersection}
    $C 
        \gets 
        \{\textrm{circle}(\partial \tilde{S}^1_{end},\varepsilon) 
        \cap 
        \textrm{circle}(\partial \tilde{S}^0_{end},\varepsilon)\}$ 

    \State  \label{alg:circleIntersectiontest}
        $x_{\text{test}}
        \gets
        x\in C|(\partial \tilde{S}^0_{end}-\partial \tilde{S}^1_{end})\boldsymbol{\times} (x-\partial \tilde{S}^1_{end}) >0 $
            \If {$x_{test} \in \mathcal{X}$}
                    \If{$f(x_\text{test}) = 0$}    \Comment{Exterior test point}
            \label{algDecision:feascheck}

            \State Append $x_{\text{test}}$ to $\overline{x}^{out}$
            \label{algDecision:assign-out}

                \Else    \Comment{Interior test point}
                    \State Append $x_{\text{test}}$ to $\overline{x}^{in}$
                    \label{algDecision:assign-in}

                \EndIf
            \Else
                \State \label{alg:outsideDomain}$\textsc{domainBoundary}(\partial \tilde{S}^1, \partial \tilde{S}^0, \partial \mathcal{X}, \varepsilon)$
            \EndIf
            \Until{
    $\min \{ \|x_{\text{test}}-\partial \tilde{S}^1_0 \|,\|x_{\text{test}}-\partial \tilde{S}^0_0 \| \}\leq \varepsilon$\\
    $ \quad \quad ~~ \textrm{and} \min \{|\partial \tilde{S}^1|,|\partial \tilde{S}^0|\} >1$
}
% \Until{$\min \{ \|x_{test}-\partial \tilde{S}^1_1 \|,\|x_{test}-\partial \tilde{S}^0_1 \|  \}\leq \varepsilon \land \min \{|\partial \tilde{S}^1|,|\partial \tilde{S}^0|\} >1$ }
    \State \Return $\partial \tilde{S}^1, \partial \tilde{S}^0$
\EndFunction
\end{algorithmic}
\end{algorithm}


The last appended points of the interior bisection sequences $\overline{x}^{in}_{end}$ and $\overline{x}^{out}_{end}$ are the first points $\partial \tilde{S}^1_0$ and $\partial \tilde{S}^0_0$ of the inner and outer point sets respectively.
These points initiate the decision boundary walk of Alg. \ref{alg:decisionStepping}.

Let $\textrm{circle}(x_c,\varepsilon)$ represent the $\varepsilon$-radius circle centered at $x_c$, or equivalently, the set $\{x: \|x-x_c\| = \varepsilon \}$.
As shown in Fig. \ref{im:decisionBoundaryWalk}, the intersection of $\textrm{circle}(\partial \tilde{S}^1_0,\varepsilon)$ and $\textrm{circle}(\partial \tilde{S}^0_0,\varepsilon)$ is first obtained.
This produces two intersection points that form set $C$ of line \ref{alg:circleIntersection} in Alg. \ref{alg:decisionStepping}.
The intersection point which has a positive cross product relative to the points $\partial \tilde{S}^1_0$ and $\partial \tilde{S}^0_0$ is selected as $x_{test}$, per line \ref{alg:circleIntersectiontest} of Alg. \ref{alg:decisionStepping}.

The selection of a positive cross product is arbitrary, and could instead be negative, so long as the direction sense is maintained throughout Alg. \ref{alg:decisionStepping}.
In the illustrative example of Fig. \ref{im:decisionBoundaryWalk}, the first $x_{test}$ point returned $f(x_{test})=1$, and is appended as $\partial \tilde{S}^1_1$ of inner set $\partial\tilde{S}^1$.
Next, the intersection points of $\textrm{circle}(\partial \tilde{S}^1_1,\varepsilon)$ and $\textrm{circle}(\partial \tilde{S}^0_0,\varepsilon)$, the last point of the $\tilde{S}^0$ set are obtained.
The point that satisfies a positive relative cross product is queried, and appended to the appropriate set.
In this manner, Alg. \ref{alg:decisionStepping} repeatedly steps by an $\varepsilon$ distance along both sides of $\partial S$ in its $\varepsilon$-neighborhood.

If a test point $x_{test}$ is found to be outside the domain $\X$, an $\varepsilon$-stepping walk is conducted along $\partial \X$, as detailed in Alg.~\ref{alg:domainBoundaryWalk} and illustrated by Fig. \ref{IM:domainBoundary}.
First, two candidate points $x_1,x_2$ on $\partial \mathcal{X}$ are identified that are $\varepsilon$ away from the $\partial \tilde{S}^1_{end}$ point.
As defined in step \ref{algBS:chooseTestPoint} of Alg.~\ref{alg:domainBoundaryWalk}, the point farther away from the $\partial \tilde{S}^0_{end}$ point is selected as $x_{test}$.
This preference ensures that the boundary intersecting $\partial \mathcal{X}$ is identified. 

The while-loop of steps \ref{algBS:whileStart}-\ref{algBS:whileEnd} continues to select test points along $\partial \X$ in the same direction sense, appending encountered interior points to $\partial \tilde{S}^1$.
This is executed until an exterior point is detected, which is appended to $\partial \tilde{S}^0$, and indicates that $\partial S$ has been detected, re-initiating Alg. \ref{alg:decisionStepping}.



