	\centering
	\scalebox{1}{\tikzfig{tikz_fig/path_product}}
	\caption{ Exemple of path product in $\cal{P}_k$}
	\label{fig:path_product}
\end{figure}

The definition implies immediately that the product of two sums of $k$-b-paths is a meet of the two in the homomorphism order restricted on the class $\cal{P}_k$. In other words:

\begin{observation}
	Given sums of $k$-b-paths $\Sigma_P$ and $\Sigma_Q$ and $\Sigma_X\in \cal P_k$ we have $\Sigma_P \wedge \Sigma_Q \la \Sigma_X$ if and only if $\Sigma_P \la \Sigma_X$ and $\Sigma_Q \la \Sigma_X$.
\end{observation}

Considering the notion of min-order on sums of $k$-b-paths, we have the following which is implied by \Cref{prop:tensorPathProduct}.

\begin{corollary}
	$\mino{\Sg P \wedge \Sg Q} \leq |\Sg P \times \Sg Q| $
\end{corollary}
   The following follows immediately from the definition.

   \begin{observation}
   	If $\Sigma_P \la \Sigma_Q$, then $\Sigma_P\vee \Sigma_Q=\Sigma_P$ and $\Sigma_P \wedge \Sigma_Q=\Sigma_Q$. 
   \end{observation}

     For the sake of completing an algebra we allow an empty set to be a $k$-b-path and denote it by $0$ with the convention that $0$ maps to every $k$-b-path.  Moreover, we denote by $1$ the directed path of length $h$ noting that all elements of $\cal{P}_k$, and thus all sums of paths in $\cal{P}_k$ map to $1$. With these notation we have the following whose details of proof we leave to the reader and for related terms we refer to \cite{Birkhoff67}. 


      \begin{proposition}
      	The system $({\cal P}_h,\vee,\wedge,0,1)$ is a distributive lattice.
      \end{proposition}


		\subsection{Mountains}


		We will work with a specific set of $k$-b-paths in which every downward move should reach height $1$ before going back up. To give a formal description we first simplify the presentation of a $k$-b-paths $P$ by uniquely associating it to a word in $\set{\up,\dw}^*$. For this, we ignore the first and last arc of $P$, and then consider the sequence of arcs in $P$ as the letters. We note that not every word corresponds to a $k$-b-path, first of all the first and the last letter should be $\up$, secondly the height of vertices should not outreach the limit of $1$ and $k - 1$. To further simplify the notation,  write $\up^i$ for an $i$ number of consecutive $\up$ and similarly $\dw_i$ for an $i$ number of consecutive downward edges. For instance, the word associated with the path in Figure~\ref{fig:path} is $word(P_1) = \up \dw \up^2 \dw_2 \up^2$. Following this terminology, the \emph{concatenation} of two $k$-b-paths $P$ and $Q$, denoted $PQ$, is defined by $word(P.Q) = word(P)word(Q)$. The concatenation of a collection of words is denoted using $\bigodot$.	       

		\begin{definition}
			 Given a sequence $\ell=(l_1,l_2, \cdots, l_r)$ where $1 \leq l_i  \leq k$, an \emph{$\ell$-mountain}, denoted $M_{\ell}$, is the $(k+2)$-b-path whose corresponding word is $\bigodot_{i \leq r} (\up^{l_i}\dw_{l_i}) \up^{k}$. For $i\leq r$ the part of the path corresponding to $\up^{l_i}\dw_{l_i}$ is said to be \emph{$i^{\text th}$-peak}, or simply a $\emph{peak}$. 

			 If $l_1,l_2, \cdots, l_r$ is a decreasing sequence of positive integers, then $M_{\ell}$ is said to be a decreasing mountain.
		 \end{definition}

	 It is easily observed that the word given in the definition satisfies the conditions of being a word for a $(k+2)$-b-path.

	 %Observe that a peak of height $l$ can be mapped to a peak of size $r$ if and only if $l \leq r$. Furthermore, if $l < r$, then the endpoints of $p_l$ can only be mapped to the same endpoint of $p_r$.

	 \begin{definition}\label{def:list_hom} A sequence $\ell=(l_1,l_2, \dots, l_p)$ where $1 \leq l_i  \leq h$ is said to be \emph{homomorphic} to the sequence $r=(r_1, r_2, \dots, r_q)$ if, first of all, $r$ is a subsequence of $\ell$ with $r_i=l_{j_i}$, secondly, $l_{1}, \dots l_{j_{1}} \leq l_{j_1}=r_1$,  thirdly, in the subsequence $l_{j_i}, \dots l_{j_{i+1}}$, $1\leq i\leq q-1$, all values are bounded above by $\max \{l_{j_i}, l_{j_{i+1}}\} = \max \{r_i, r_{i+1}\}$. 
	 \end{definition}

	 	In the next proposition we show that being homomorphic between two sequences is the same as existence of a homomorphism between the corresponding mountains.

	 	\begin{proposition}
			\label{prop:list_hom}
	 		Given two mountains $M_{\ell}$ and $M_{r}$ with their corresponding sequences $\ell=(l_1,l_2, \dots, l_p)$ and $r=(r_1, r_2, \dots, r_q)$ we have $M_{\ell}\to M_{r}$ if and only if $\ell$ is homomorphic to $r$.
	 	\end{proposition} 

 	\begin{proof}
 		\boxed{\Ra} Suppose that $l$ is homomorphic to $r$. We may find a homomorphism of $M_{\ell}$ to $M_{r}$ by mapping all the peaks at $l_{k_i}, \dots l_{k_{i+1}}$ to the $\max \{r_{k_i}, r_{k_{i+1}}\}$, taking an arbitrary choice when $r_{k_i}=r_{k_{i+1}}$. 

		\boxed{\La} Suppose $M_\ell$ is homomorphic to $M_r$, we first note that not every homomorphism of $M_{\ell}$ to $M_{r}$ is of the form defined in the previous part. However, to prove this direction of the claim, given a homomorphism, $\psi$, of $M_{\ell}$ to $M_{r}$, using the restriction of $\psi$ on vertices at height 1 of the two mountains we will find a mapping of $\ell$ to $r$. 

 		Let $x_1, x_2, \dots, x_{p+1}$ be the vertices of $M_{\ell}$ at height $1$ and $y_1, y_2, \dots, y_{q+1}$ be the vertices of $M_{r}$ at height 1, each sequence ordered by the distance from the beginning of the path. The mapping $\psi$ must map $x_i$'s to $y_j$'s. 
		Observe that if $\phi(x_i) = y_j$, then there are three possible values for $\phi(x_{i+1})$: 
		\begin{itemize}[noitemsep]
		\item $\phi(x_{i+1}) = y_{j-1} \AND l_i = r_{j-1} \OR$
		\item $ \phi(x_{i+1}) = y_j \AND l_i \leq \max(r_{j-1},r_j) \OR$
		\item $  \phi(x_{i+1}) = y_{j+1} \AND l_j = r_j$ .
		\end{itemize}
		In order for this property to be well defined for $j=1 \AND j=q+1$, we define $r_0 = 0$ and $r_{q+1} = h$ (the height of the mountain).
		We construct a subsequence $(x_{k_j})$ of the $x_i$'s in the following way: 
		\begin{itemize}[noitemsep]
		\item $k_1$ is the maximal index such that $\psi(x_{k_1}) = y_1$ and all peaks until $l_{k_1}$ have height at most $r_1$.
		\item $k_{j+1}$ is the maximal index bigger than $k_j$ such that $\psi(x_{k_{j+1}}) = y_{j+1}$ and all peaks between $l_{k_j} \AND l_{k_{j+1}}$ have height at most $\max(r_j,r_{j+1})$.

		\end{itemize}


		What remains to show is that the sequence of $k_j$'s is well defined. To this end, all one needs to do is to show that, having defined $k_j$, there exists a $t> k_j$ such that $\psi(x_t)=y_{_{j+1}}$. For this, in fact we show that $\psi(x_{k_{_{j+1}}})=y_{_{j+1}}$. Towards a contradiction, suppose that $\psi(x_{k_j\!+1})\neq y_{j+1}$, then $\psi(x_{k_{j}\!+1})\in \set{x_{k_{j-1}}, x_{k_{j}} }$ and, furthermore, there exists a first index $t > k_j$, such that $\psi(x_t)=y_{j+1}$. Then $\set{ x_{k_{j}} , \dots, x_{t-1}}$ is surjectively mapped to $\set{y_{s}, \dots, y_{j}}$ for some $s\leq j$. Let $r_{s'}$ be the largest height of a peak between $y_{s}$ and $y_j$. Hence, for all $i \in [k_{s'}, t[$, $l_i \leq r_{s'}$. But in our process of choosing $k_{s'}$, we should have chosen a larger index. This contradiction verifies the claim that $\psi(x_{k_j\!+1}) = y_{j+1}$, completing the proof.
 	\end{proof}


