\begin{lemma} \label{lem:conecommute}
	Let $G_1, \dots, G_\ell$ be  a finite sequence of nontrivial oriented graphs. The retract of $\prod_{i \leq \ell} \cone G_i$ to a core of itself induces a homomorphism of $\prod_{i \leq \ell} G_i$ to itself.
	In particular, the diagram on the right commutes.
\end{lemma}

\begin{proof}
	In the \Cref{lem:conecommute}, the top horizontal arrow is the natural inclusions induced by the inclusion of $G_i$ in $\cone G_i$.
	Let $\phi$ be a retract of $\prod_{i \leq \ell} \cone G_i$ to a core of itself. 
	Because each $G_i$ is nontrivial, by considering induced subgraphs isomorphic to $\cone \vec P_2$, we have $\phi(\apex {G_1},\dots,\apex {G_\ell}) = (\apex {G_1},\dots,\apex {G_\ell})$.
	Then the neighborhood of $(\apex {G_1},\dots,\apex {G_\ell})$ is $(V(\prod_{i \leq \ell} G_i))$ and must map to the neighborhood of $\phi(\apex {G_1},\dots,\apex {G_\ell})$. In other words $\phi(\prod_{i \leq \ell} G_i) \subseteq (\prod_{i \leq \ell} G_i)$.
	And since $\phi$ is a retract $\core{\phi(\prod\limits_{i \leq \ell} G_i)} \cong \core{\prod\limits_{i \leq \ell} G_i}$. 
\end{proof}

The following is the key tool towards building a family of digraphs whose product is a core.

\begin{theorem}
	For any pair $G$ and $H$ of orthogonal and incomparable oriented graphs the product of their cones, $\cone G \times \cone H$, is a core.
\end{theorem}

\begin{proof}
	Let $\phi$ be a retract of $\cone G \times \cone H$ to (one of) its core. The claim of the theorem is that $\phi$ is the identity. We will prove this separately on the four parts $\set{(\apex G, \apex H)}$, $ G \times \apex H$, $\apex G \times  H$, and $V(G \times H)$.

	For the first part, we have already seen in \Cref{lem:conecommute} that $\phi(\apex G,\apex H) = (\apex G,\apex H)$.
	Consider the restriction of $\phi$ on the second part, i.e.,  $G \times \apex H $. We first show that $\phi$ maps this set of vertices to itself.
	Toward a contradiction, suppose a vertex $(u, \apex H)$ of this set is mapped to another part. Thus we have three possibilities.

	\begin{itemize}
		\item $\phi(x,\apex H)  = (\apex G,y)$: In this case, since $\phi$ is a retract and $(\apex G,y) \in Im(\phi)$, we have that $\phi(\apex G,y) = (\apex G,y)$ which is impossible because $(x,\apex H) \digon (\apex G,y)$ and $\phi^2 = \phi$.

		\item $\phi(u,\apex H)=(\apex G,\apex H) $: In this case, since $ (u, \apex H)$ is adjacent to every vertex in $\apex G \times H$ (by digons) and since the neighborhood of $(\apex G, \apex h)$ is $G \times H$, we have $\phi(\apex G \times H) \subset G \times H$. Furthermore, any other $(v, \apex H)$ is also adjacent with digons to $\apex G \times H$, therefore $\phi(v, \apex H) = (\apex G, \apex H)$ \emph{i.e.} $G \times \apex H = (\apex G, \apex H)$.

		Next we claim that if $\phi(\apex G, x) = (v,x')$, then $x'$ dominates $x$ (i.e. $\vec N (x) \subset \vec N (x')$ and  $\rvec{N} (x) \subset \rvec{N} (x')$). As $H$ is a core, this would imply $x=x'$.
		%Then let ${\phi_\star: H \ra G}, y \mapsto \pi_G\circ \phi(\apex G,y)$. We will show that it is a homomorphism.
		Let $y$ be a neighbor of $x$, and, by symmetry,  assume that $y$ is an out-neighbour of $x$ .

		By \Cref{lem:conecommute}, we have that $\phi|_{G \times H}$ is a retract of $G \times H$. By \Cref{prop:project+hom} there exists a vertex $w$ such that $(w,y) \in Im(\phi)$.
		Recall that $\phi(\apex G, x) = (v,x')$, moreover, since $\phi$ is a retract and $(w,y)\in Im(\phi)$, $\phi(w,y) = (w,y)$. Since $(w,y)$ is an out-neighbour of $(\apex G, x)$ in $\cone G \times \cone H$ we have $(w,y) \tikzRarrow (v,x')$ which means, in particular, that $y$ is an out-neighbour of $x'$. This complete the proof of $x'$ dominating $x$ implying $\phi(\apex G,x) = (v,x)$.

		Now we claim that $H \ra G$ which is in contradiction with $H$ and $G$ being incomparable.
		Let $x \tikzRarrow y$  be an arc of $H$. Let $\phi(\apex G,x) = (v,x)$, $\phi(\apex G,y) = (w,y)$. Observe that $(\apex G, x) \tikzRarrow (w,y)$. Applying $\phi$ and noting that it is a retract, we have $(v,x) \tikzRarrow (w,y)$ and thus $v \tikzRarrow w$. This proves that the restriction of $\phi$ on $\apex G \times H$ composed with the projection of $G \times H$ to $G$ is a homomorphism of $H$ to $G$.

		\item $\phi(x,\apex H) \in G \times H$: In this case, considering the digons in \Cref{fig:product_cones} connecting $\apex G \times H$ and $G \times \apex H$, we conclude that $\phi(\apex G, \times H) = (\apex G,\apex H)$. Symmetrically to the above case, we reach a contradiction.
	\end{itemize}		
		Having proved $\phi(G\times \apex H) \subset G\times \apex H$ we aim to prove that $\phi|_{G\times \apex H}$ is the identity. Let $\phi(u,\apex H) = (u',\apex H)$. Once again, we show that $u'$ dominates $u$ which would imply $u'=u$.
		To that end, consider a neighbor $v$ of $u$, and, by symmetry, assume $u \tikzRarrow v$. Then, by \Cref{lem:conecommute} and \Cref{prop:project+hom}, there exists $(v,y) \in Im(\phi)$. Observe that $(u, \apex H) \tikzRarrow (v,y)$, applying $\phi$ which is a retract, we get $(u', \apex H) \tikzRarrow (v,y)$. In particular $u' \tikzRarrow v$ meaning that $u'$ dominates $u$.

		By symmetry $\phi|_{\apex G\times H}$ is also the identity.
		To see that $\phi|_{G\times H}$ is the identity, we note that the neighborhood of a vertex $(u,x)$ in $\apex G\times H \cup G\times \apex H$ uniquely determines $(u,x)$. 
\end{proof}

So far, we have provided a sufficient condition for the product of two digraphs to be a core. In the next theorem, we do the same for an arbitrary number of digraphs, but for the theorem to work, the condition we require are stronger.


\begin{theorem}\label{thm:VSCmultiple}
	If $\cal G = \set{G_1,\dots ,G_\ell}$ is a family of oriented incomparable cores verifying:
	\begin{enumerate}
		\item[(a)] $\forall G \in \cal G$, we have $ \prod\limits_{\substack{H \in \cal G \\ H \neq G}}H \not \ra G$ and $\prod\limits_{\substack{H \in \cal G \\ H \neq G}}H \ra \cone G$
		\item[(b)] $\cal G$ is an orthogonal family: $ \forall G \in \cal G$, we have $ \prod\limits_{H \in \cal G}H \rra G$, 
	\end{enumerate}
	then $ \prod\limits_{G \in \cal G} \cone G \tx{ is a core }$
\end{theorem}

\begin{proof}
	Consider a retract $\phi$ of $ \prod\limits_{G \in \cal G} \cone G$ to itself, we shall prove that $\phi$ is the identity.

	We consider vertices of the product where each coordinate except one is an apex and refer to them as \emph{basis elements}.
	By symmetry of the coordinates, we work with vertices of the form $(x_1,\apex {G_2} \dots \apex{G_{\ell}})$ and show that:

    \vspace{5pt}
    \textbf{Claim 1:} The restriction of $\phi$ onto basis elements is the identity.\\
	We first show that  $\phi(x_1,\apex{G_2}, \dots, \apex{G_{\ell}}) \not \in \apex{G_1}\! \times \cone G_2 \times \dots \times \cone G_\ell  $. Assume to the contrary that $\phi(x_1,\apex{G_2}, \dots, \apex{G_{\ell}}) = (\apex{G_1},\alpha_2,\dots,\alpha_\ell)$, observe that $\apex{G_1}\! \times G_2 \times \dots \times G_\ell$ is the set of vertices each adjacent to the vertex $(x_1,\apex{G_2} ,\dots, \apex{G_{\ell}})$ with a digon. Therefore, for each element $(\apex{G_1}, x_2, \dots , x_\ell)$ of $\apex{G_1}\! \times G_2 \times \dots \times G_\ell$, its image under $\phi$ is adjacent to $\phi(x_1,\apex{G_2}, \dots, \apex{G_{\ell}})$ with a digon. It follows that $\phi(\apex{G_1}, x_2, \dots , x_\ell) \in G_1 \times \cone G_2 \times \dots \times \cone G_\ell$. In other words $\pi_1 \circ \phi(\apex{G_1}\! \times G_2 \times \dots \times G_\ell) \subseteq V(G_1)$.
		Independently, using \Cref{lem:conecommute}, we have $\pi_1 \circ \phi(G_1\! \times G_2 \times \dots \times G_\ell) \subseteq V(G_1)$.

		Combining the two together, we conclude that $\pi_1 \circ \phi$ maps $\cone G_1\! \times G_2 \times \dots \times G_\ell$ to $ G_1$. 
		But by the second part of the assumptions $(a)$, we have $G_2 \times \dots \times G_\ell \ra \cone G_1$. Thus $\cone G_1\! \times G_2 \times \dots \times G_\ell$ is homomorphically equivalent to $G_2 \times \dots \times G_\ell$. Hence we have that $G_2 \times \dots \times G_\ell \to G_1$, however this contradicts the fist part of assumption $(a)$.

		\vspace{5pt}

		To complete the proof of Claim 1, assume $\phi(x_1,\apex{G_2} \dots \apex{G_{\ell}}) \in x_1'\! \times \cone G_2 \times \dots \times \cone G_\ell  $, with $x_1' \in G_1$. 
	    We aim to prove that $x_1'$ dominates $x_1$ which would imply $x_1'=x_1$. Toward that, consider a neighbor $y_1$ of $x_1$ in $G_1$. By symmetry, assume $x_1 \tikzRarrow y_1$. By assmuption \emph{(b)} and using the \Cref{prop:project+hom}, we know the existence of $y_2, \dots,y_\ell$ such that $(y_1,y_2,\dots, y_\ell) \in Im(\phi)$.
	    Observe that $(x_1,\apex{G_2} \dots \apex{G_{\ell}}) \tikzRarrow (y_1,y_2,\dots, y_\ell)$. Applying $\phi$, and noting that it is a retract, we get $\phi(x_1,\apex{G_2} \dots \apex{G_{\ell}})\tikzRarrow (y_1,y_2,\dots, y_\ell)$. Then looking at the first coordinate, we get $x_1' \tikzRarrow y_1$, showing that $x_1'$ dominates $x_1$.

		\vspace{5pt}

	\textbf{Claim 2:} $\phi|_{G_1 \times \dots \times G_\ell}$ is the identity.\\
	Let $(x_1,\dots,x_\ell) \in G_1 \times \dots \times G_\ell$. By the \Cref{lem:conecommute}, we already know that $\phi(x_1,\dots,x_\ell) \in G_1 \times \dots \times G_\ell$. Hence, we assume $\phi(x_1,\dots,x_\ell) = (x_1',\dots,x_\ell') $.
	By the symmetry of the coordinates, it is enough to show that $x_1'$ dominates $x_1$, and since $G_1$ is a core, it would imply $x_1'=x_1$.

	Let $y$ be a neighbor of $x_1$ in $G_1$, and by symmetry, assume that $x_1 \tikzRarrow y$. Then $(x_1,\dots,x_\ell) \tikzRarrow (y, \apex{G_2}, \dots, \apex{G_{\ell}})$.
	By applying $\phi$ we have $(x_1',\dots,x_\ell') \tikzRarrow \phi(y, \apex{G_2}, \dots, \apex{G_{\ell}})$. In particular, by restriction to the first coordinate, we conclude $x'_1 \tikzRarrow y$ meaning that $x_1'$ dominates $x_1$ and thus $x_1' = x_1$. Similarly, we have the same for all other coordinates, therefore $\phi(x_1,\dots,x_\ell) = (x_1,\dots,x_\ell)$, and $\phi$ is the identity on $G_1 \times \dots \times G_\ell$.
	\vspace{5pt}

	Next, we have to prove the same on the remaining vertices of $\prod\limits_{G \in \cal G} \cone G$. 
	For this, we will need to pay close attention to the vertices with empty out-neighborhood or in-neighborhood in $G_i$. We write $\vec{N}_{G_i}(\alpha_i)$ (\emph{resp.} $\rvec{N}_{G_i}(\alpha_i)$) for the out-neighborhood in $G_i$  (\emph{resp.} in-neighborhood) of $\alpha_i \in \cone G_i$. In particular $\vec{N}_{G_i}(\apex{G_i}) = V(G_i)$.

	Since the graphs are cores, they cannot have any isolated vertices, except if $\cal G = \set{K_1}$. 
	Furthermore, we can assume that each $G_i$ contains a $\vec P_3$ as a subgraph. Otherwise, since they are incomparable cores, this would imply $\cal G = \set{\vec P_2}$. Therefore, in every $G_i$, there is a vertex $z_i$ such that $N_{G_i}^\ra(z_i) \neq \emptyset$ and $N_{G_i}^\la(z_i) \neq \emptyset$.

	\textbf{Claim 3:} If $\phi(\alpha_1,\dots,\alpha_\ell) = (\alpha_1',\dots,\alpha_\ell')$ then $\alpha_i' = \apex{G_i} \iff \alpha_i = \apex{G_i}$.\\
	We consider several cases:
	\begin{enumerate}
	\item[I.] Assume $\alpha_1 = \apex{G_1}$ and $\vec{N}_{G_i}(\alpha_i) \neq \emptyset$ for $i=2, \ldots, \ell$. Toward a contradiction, assume $\alpha_1' = x_1'\in G_1$.
	For $i \neq 1$, chose $y_i \in G_i$ such that $\alpha_i \tikzRarrow y_i$. Then $(\apex{G_1},\alpha_2,\dots,\alpha_\ell) \tikzRarrow (x_1',y_2,\dots,y_\ell)$. From Claim 2., we have that $(x_1',y_2,\dots,y_\ell)$ is fixed by $\phi$, therefore $\phi(\apex{G_1},\alpha_2\dots,\alpha_\ell) = (x_1',\alpha_2'\dots,\alpha_\ell') \tikzRarrow (x_1',y_2,\dots,y_\ell)$. That would imply a loop on $x_1'$ in $G_1$ which is a contradiction.

	\item[II.] Assume $\alpha_1 = x_1 \neq \apex{G_1}$.
	Let $\beta_i$ be a vertex of $\cone G_1$ such that $\alpha_i \digon \beta_i$ and $N_{G_i}^\ra(\beta_i) \neq \emptyset$. It exists because one can chose $\apex{G_i}$ if $\alpha_i \neq \apex{G_i}$, or $z_i$ if $\alpha_i = \apex{G_i}$. Observe that 
	$(x_1,\alpha_2,\dots,\alpha_\ell) \digon (\apex{G_1},\beta_2,\dots,\beta_\ell)$. We have already seen in I that $\phi(\apex{G_1},\beta_2\dots,\beta_\ell)$ preserves the first coordinate, and since $\phi(\apex{G_1},\beta_2\dots,\beta_\ell) \digon \phi(x_1,\alpha_2,\dots,\alpha_\ell)$, we have $\alpha_1' \digon \apex{G_1}$ and, in particular, $\alpha_1' \neq \apex{G_1}$

	\item[III.] Assume $\alpha_1 = \apex{G_1}$,  with no assumption on the $\alpha_i$ this time. Using the same $\beta_i$ as in II and any $x_1 \in G_1$, since $(\apex{G_i},\alpha_2,\dots,\alpha_\ell) \digon (x_1,\beta_2,\dots,\beta_\ell)$, we have $\phi(\apex{G_i},\alpha_2,\dots,\alpha_\ell) \digon \phi(x_1,\beta_2,\dots,\beta_\ell)$. We have  $\alpha_1 \digon \pi_{1} \circ \phi(x_1,\beta_2,\dots,\beta_\ell)$. By II, $\pi_{1} \circ \phi(x_1,\beta_2,\dots,\beta_\ell) \ni G_1$ and, therefore, $\alpha_1 = \apex{G_1}$.

	\end{enumerate}

	 %Now it remain to show that $\phi$ also preserves the value of non-apex vertices. Take $(x_1,\alpha_2\dots,\alpha_\ell) \in G_1\! \times \cone G_2 \times \dots \times \cone G_\ell$, and let $(x_1',\alpha_2',\dots,\alpha_\ell') = \phi(x_1,\dots,\alpha_\ell)$. 	\vspace{5pt}

	\textbf{Claim 4:}  Assume $\phi(x_1,\alpha_2,\dots,\alpha_\ell) = (\alpha_1',\alpha_2',\dots,\alpha_\ell')$. If $\forall i, i\neq 1,  \vec N_{G_i}(\alpha_i) \neq \emptyset$ and $\rvec{N}_{G_i}(\alpha_i) \neq \emptyset$, then $\alpha_1' = x_1$.\\
	 By Claim 3, we know that $\alpha_1' \in G_1$ hence we write $\alpha_1' = x_1'$.
	 Consider a neighbor $y_1$ of $x_1$. By symmetry, assume $x_1\tikzRarrow y_1$. Then for $i>1$, chose $y_i \in G_i$ such that $\alpha_i \ra y_i$.
	 Then $(x_1,\alpha_2\dots,\alpha_\ell) \tikzRarrow (y_1,\dots,y_\ell)$. By applying $\phi$, noting that, by Claim 2, $\phi$ fixes $(y_1,\dots,y_\ell)$, we get $(x_1',\alpha_2',\dots,\alpha_\ell') \tikzRarrow  (y_1,\dots,y_\ell)$. In particular, $x_1' \tikzRarrow y_1$. 
	 Therefore $x_1'$ dominates $x_1$ in $G_1$ and hence $x_1'= x_1$.
	 \vspace{5pt}

	To prove the theorem, we consider $\phi(\alpha_1, \dots, \alpha_\ell) = (\alpha_1', \dots, \alpha_\ell')$. If $\alpha_1 = \apex{G_1}$ then, by Claim 3, $\alpha_1' = \apex{G_1}$. Otherwise let $\alpha_1 = x_1$ then by Claim 3, $\alpha_1' = x_1'$.
	Note that now, we have no restriction on the $\alpha_i$'s. Consider $y_1$ a neighbor of $x_1$, by symmetry, assume $x_1 \tikzRarrow y_1$. For $i\neq 1$, let $\beta_i \in \set{\apex{G_i}, z_i}$ such that $\alpha_i \digon \beta_i$. Then $\phi(x_1,\alpha_2\dots,\alpha_\ell) \tikzRarrow \phi(y_1,\beta_2,\dots,\beta_\ell)$. Observing that $\beta_i$'s satisfy the condition of Claim 4, $y_1$ is the first coordinate of $\phi(y_1,\beta_2,\dots,\beta_\ell)$. Hence $x_1' \tikzRarrow y_1$. Therefore $x_1'$ dominates $x_1$ in $G_1$ thus $x_1'=x_1$. 
\end{proof}


\section{Decreasing mountains}
\label{sec:Decreasing_mountains}

In the previous section, we have provided conditions under which the tensor product of a family of digraphs is a core. Here we provide examples. 
\begin{definition}
	A mountain $M_{\partial}$ is said to be \emph{decreasing} if the corresponding sequence $\partial = (\partial_1, \dots, \partial_\ell)$ is (strictly) decreasing. The set of all decreasing mountains of height $h$ with $\ell$ peaks satisfying $\partial_1 = h-2$ is denoted by $DM_{h,\ell}$ 
\end{definition}

We show that $DM_{h,\ell}$ satisfies the conditions of \Cref{thm:VSCmultiple}. This is done in the next three propositions.


\begin{figure}[htb] 
 	\centering
 	\scalebox{.8}{\tikzfig{tikz_fig/omega_mountain}}
 	\caption{Example of decreasing mountains, and the sequence $\Omega$ defined in the proof of \Cref{mountain_indep}} \label{fig_omega_mountain}
\end{figure}

\begin{proposition}
	For every member $M_{\partial}$ of $DM_{h,l}$ we have: $\prod\limits_{M_{\delta} \neq M_{\partial}}{M_{\delta}} \ra \cone M_{\partial}$
\end{proposition}
\begin{proof}
	In fact each $M_{\delta}$ maps to a digon, therefore $\prod\limits_{M_{\delta} \neq M_{\partial}}{M_{\delta}}$ maps to a digon.
\end{proof}

\begin{proposition}
	For every member $M_{\partial}$ of $DM_{h,l}$ we have: $\prod\limits_{M_{\delta}\in DM_{h,l}}{M_{\delta}}\rra M_{\partial}$
\end{proposition}
\begin{proof}
	As seen in \Cref{prop:tensorPathProduct}, $\prod\limits_{M_{\delta} \neq M_{\partial}}{M_{\delta}}$ contains an $h$-bounded path. Hence, any mapping of it to $ M_{\partial}$ must be surjective.
\end{proof}

\begin{proposition} \label{mountain_indep}
	For every member $M_{\partial}$ of $DM_{h,l}$ we have: $\prod\limits_{M_{\delta} \neq M_{\partial}}{M_{\delta}} \not \ra  M_{\partial}$
\end{proposition}
\begin{proof}
	Fix $\partial$ a decreasing sequence starting at $\partial_1 = h-2$.
	We shall construct a sequence (not necessarily decreasing) $\Omega$ such that $M_\Omega \not \ra M_\partial$ but for any $\delta \neq \partial$, $M_\Omega \ra M_\delta$.

	Let $[m]\setminus \set{k}$ denote the (decreasing) sequence $m,m-1,\dots,k+1,k-1,\dots,1$.
	We define $\Omega$ as concatenation of many sequences as follows:
	$$\Omega = \partial_1 \cdot \left ([\partial_1-1]\setminus \set{\partial_2}\right ) \cdot \partial_2 \cdot  \left ([\partial_2-1]\setminus \set{\partial_3}\right )  \ldots  \partial_{\ell - 1}  \cdot \left ([\partial_{\ell-1}-1]\setminus \set{\partial_l}\right ) .$$

	First, we show that $\Omega$ doesn't contain $\partial$ as a subsequence. This which would imply by \Cref{prop:list_hom} that $M_\Omega \not \ra M_\partial$.
	Toward a contradiction, assume that $\partial$ is a subsequence of $\Omega$, then $\partial_2$ must appear in the subsequence, it cannot appear inside $[\partial_1-1]\setminus \set{\partial_2}$, therefore, it must appear inside the part: $\partial_2 \cdot  \left ([\partial_2-1]\setminus \set{\partial_3}\right )  \ldots  \partial_{\ell - 1}  \cdot \left ([\partial_{\ell-1}-1]\setminus \set{\partial_l}\right )$.
	As $\partial_3$ must appear after $\partial_2$, and cannot appear in $[\partial_2-1]\setminus \set{\partial_3}$, it must appear in $\partial_3 \cdot  \left ([\partial_3-1]\setminus \set{\partial_4}\right )  \ldots  \partial_{\ell - 1}  \cdot \left ([\partial_{\ell-1}-1]\setminus \set{\partial_l}\right )$. Continuing this process, there is no place for $\partial_\ell$ to appear.
	\vspace{5pt}

	Finally, we show that given a $\delta \neq \partial$, we have $M_\Omega \ra M_\delta$.
	Since $\delta \neq \partial$, there exists a first index $t$ such that $\partial_t \notin \delta$, and we can decompose $\delta$ in the following way: 
	$$\delta = \partial_1\cdot\delta|_{]\partial_2,\partial_1[}\cdot \partial_2\cdot\delta|_{]\partial_3,\partial_2[} \dots \partial_{t-1} \cdot \delta|_{]0,\partial_{t-1}[}.$$
	Where $\delta|_{]i,j[}$ is the (possibly empty) subsequence of $\delta$ of the values in $[i,j]$.
	This decomposition corresponds to a natural subsequence of $\Omega$, as $\delta|_{]\partial_i,\partial_{i+1}[} $ is a subsequence of $[\partial_i] \setminus \set{\partial_{i+1}}$, and $\delta|_{]0,\partial_{t-1}[}$ is a subsequence of $[\partial_{t-1}] \setminus \set{\partial_{t}}$.

	With this presentation of $\delta$ as a subsequence of $\Omega$, it remains to verify the last two conditions of $\Cref{def:list_hom}$, in order to verify that $\Omega$ is homomorphic to $\delta$ that is to say, $M_\Omega \ra M_\delta$.
	The second condition of the definition is trivial because $\delta_1 = \Omega_1 = \partial_1 = h+2$.
	By the nature of our choices, the subsequence of $\Omega$ in between $\delta_i$ and $\delta_{i+1}$ is bounded by $\delta_i$
\end{proof}

\begin{theorem}\label{thm:M-partial}
	For any $h>l+2$, $\prod\limits_{M_\partial \in DM_{h,\ell}} \cone M_\partial$ is a core.
\end{theorem}

There is a one-to-one correspondance between elements of $DM_{h,\ell}$ and $\ell$-subsets of $[h-2]$. In other words, $|DM_{h,\ell}|=\binom{h-2}{\ell}$. Taking $\ell = k$ and $h=2k+2$, we have a set of $\binom{2k}{k}$ digraphs, the largest of which has $3k^2+3k+2$ vertices and the smallest of which has $k^2+5k+2$ vertices. Therefore:
$$ \left |\core{ \textstyle \prod\limits_{M_\partial \in DM_{2k+2,k}} \cone M_\partial} \right |  \geq (k^2+5k+2)^{\binom{2k}{k}}$$

\begin{proposition}
	There exists a family of digraphs, each of order at most $n$, whose product has a core of order $\Omega\left (n^{\frac{2^{^{\sqrt{n}}}}{\sqrt{n}}}\right )$
\end{proposition}

\section{From digraphs to graphs}\label{sec:Digraph-Graph}

In this final section we show that the family of digraphs we built whose product was a core, can be transformed into a family of graphs having the same property.
The idea is to replace every oriented edge with a non-oriented gadget where the structure of the gadget captures the orientation. The gadget we use is the graph $K_2\Bowtie C_5$. Given a digraph $D$ we build a graph $G[D]$ by replacing each edge with a (vertex disjoint) copy of $K_2\Bowtie C_5$ where the head is identified with a vertex from the $K_2$ part and the tail is replaced with a vertex from $C_5$-part. See \Cref{fig:wheel} for an example. We show that the following holds.

\begin{figure}[htb]
	\centering
	\scalebox{1}{\tikzfig{tikz_fig/wheel}}
		\caption{An example of $G[D]$}
		\label{fig:wheel}		
\end{figure}



\begin{theorem}\label{thm:D1*D2}
	Given two digraphs $D_1$ and $D_2$, if the underlying graph of $D_2$ is 4-colorable, then $D_1\ra D_2$ if and only if $G[D_1] \ra G[D_2]$. Furthermore, restriction of any homomorphism $\psi: G[D_1] \ra G[D_2]$ to the vertices of $D_1$ is a homomorphism of $D_1$ to $D_2$.
\end{theorem}

\begin{proof}
	We first observe that there are three possible homomorphic images of $K_2\Bowtie C_5$: the graph itself, one obtained by identifying two nonadjacent vertices of $C_5$ (which is isomorphic to $K_6-E(P_3)$), and $K_5$. 

	Let $\phi$ be a homomorphism of $G[D_1]$ to $G[D_2]$. For an arc $a_1= u_1 \tikzRarrow v_1$ of $D_1$ we claim that the copy of the gadget corresponding to $a_1$ in $G[D_1]$ is mapped to a copy built on an arc $a_2=u_2 \tikzRarrow v_2$ of $D_2$. This would complete the proof of the theorem because such a mapping must map $K_2$ and $C_5$ to the corresponding parts. 

	To prove the claim of the theorem, let $H_1$ be the copy of the gadget built on the arc $a_1$. As the underlying graph of $D_2$ is 4-colorable, $\phi(H_1)$ must contain a vertex $x$ not in $V(D_2)$. Suppose this vertex is in the copy $H_2$ of the gadget corresponding to an arc $a_2$ of $D_2$. As $H_2$ contains no $K_5$, if $\phi(H_1)$ is a $K_5$ or $K_6-E(P_3)$, then at least one of its vertices, say $y$, is not in $H_2$. Then the vertices of $\phi(V(H_1))\cap \{u_2, v_2\}$ (a subset of vertices of the arc $a_2$) separate the two vertices, $x$ and $y$ of $\phi(H_1)$, but both $K_5$ and $(K_6-E(P_3)$ are 3-connected. Thus $\phi(H_1)$ is isomorphic to $K_2\Bowtie C_5$, and can only be the copy built on arc $a_2$. Furthermore, the $K_2$ part of $H_1$ must maps to the $K_2$ part of $H_2$ which proves the second part of the claim.	
\end{proof}

As the diagonal entries of $G\times G$ induce an isomorphic copy of $G$, we have the following observation.

\begin{observation}
	Given digraphs $D_1$ and $D_2$ the graph $G[D_1\times D_2]$ is a subgraph of $G[D_1]\times G[D_2]$.
\end{observation}

With a repeated application of this observation, we concluded that for any (finite) family $\mathcal{D}$ of digraphs the graph $ G[\footnotesize  \prod\limits_{D \in \mathcal{D}} D]$ is a subgraph of $ {\prod\limits_{D \in \mathcal{D}} G[D]}$. As a final step we show that under certain conditions, the core of $ {\prod\limits_{D \in \mathcal{D}} G[D]}$ is at least as large as the core of  $ G[\footnotesize  \prod\limits_{D \in \mathcal{D}} D]$.

\begin{theorem}
If $\mathcal{D}$ is a (finite) family of digraphs each of whose underlying graph is 4-colorable, then $$ \left| G\left [\core{\textstyle\prod\limits_{D \in \mathcal{D}} D} \right ] \right| \leq \left|\core{\textstyle\prod\limits_{D \in \mathcal{D}} G[D]}\right|.$$	
\end{theorem}


\begin{proof}
	Let $\psi$ be a mapping of $\prod\limits_{D \in \mathcal{D}}G[D]$ to (one of) its core. Let $\psi_i$ be the projection of $\core{\textstyle\prod\limits_{D \in \mathcal{D}} G[D]}$ to $G[D_i]$. Since $G[\prod\limits_{D \in \mathcal{D}} D]$ is a subgraph of $\prod\limits_{D \in \mathcal{D}}G[D]$, the mapping $\psi_i$ can be reduced to a mapping $\psi_i'$ of $G[\prod\limits_{D \in \mathcal{D}}D]$ to $G[D_i]$.

	Since each $D_i$ is 4-colorable, the product $\prod\limits_{D \in \mathcal{D}}{D}$ is also 4-colorable. Thus, by \Cref{thm:D1*D2}, $\psi'_i$ induces a mapping of $\prod\limits_{D \in \mathcal{D}}D$ to $D_i$. Hence, $\psi$ induces a mapping of $\prod\limits_{D \in \mathcal{D}}D$ to itself which should contain a copy, say $H$, of its core. Applying \Cref{thm:D1*D2} again we conclude that the image of $H$ must contain a copy of $G[H]$.
\end{proof}


As a corollary, when we take the family $DM_{h, l}$ consisting of the cones of decreasing mountains, and build $G[\cone{P}]$ for each $P\in  DM_{h, l}$, their product contains $G[H]$ where $H$ is the digraph $\prod\limits_{P\in D_{h,l}}{\cone P}$. Observe that if $P$ has $n$ vertices, then $\cone P$ has $n+1$ vertices and $3n-1$ edges. Hence $G[\cone{P}]$ has $n+1+5(3n-1)=16n-4$ vertices. Bounding the number of vertices of graphs in $DM_{2k, k}$ below and above by $k^2+5k+2$ and  $3k^2+3k+2$ we have the following conclusion based on the core of the product  $\prod\limits_{P\in D_{2k,k}}{\cone P}$.

\begin{corollary}
	There is a family of $\binom{2k}{k}$ graphs each of which has its number of vertices between $16k^2+80k+12$ and $48k^2+48k+12$  where the core of the product has more than $4(16k^2+80k+2)^{\binom{2k}{k}}$.
\end{corollary}

