\subsubsection{Proof for Claim~\ref{claim - fj-monotonicity}}

\label{app: proof for fj monotonicity}

$\mW$ is chosen to optimize the following function according to our setup
\[
 \max  \sum_{i \in \gB} v_i(\mW) - \sum_{j \in \gS} \hat{c}_j f_j(\mW)
\]


Suppose for contradiction, there exist two reported costs $c_j < c_j'$ such that:
\[
    f_j(\mW(c_j', \vc_{-j})) > f_j(\mW(c_j, \vc_{-j}))
\]

By optimality of the allocation $\mW$, we have that:
\begin{equation}
\begin{aligned}
&\sum_{i \in \mathcal{B}} v_i(\mW(c_j, \vc_{-j})) - c_j f_j(\mW(c_j, \vc_{-j})) - \sum_{k \neq j} c_k f_k(\mW(c_j, \vc_{-j})) \\
&\quad \geq  \sum_{i \in \mathcal{B}} v_i(\mW(c_j', \vc_{-j})) - c_j f_j(\mW(c_j', \vc_{-j})) - \sum_{k \neq j} c_k f_k(\mW(c_j', \vc_{-j}))
\end{aligned}
\end{equation}

and similarly,

\begin{equation}
\begin{aligned}
&\sum_{i \in \mathcal{B}} v_i(\mW(c_j', \vc_{-j})) - c_j' f_j(\mW(c_j', \vc_{-j})) - \sum_{k \neq j} c_k f_k(\mW(c_j', \vc_{-j})) \\
&\quad \geq  \sum_{i \in \mathcal{B}} v_i(\mW(c_j, \vc_{-j})) - c_j' f_j(\mW(c_j, \vc_{-j})) - \sum_{k \neq j} c_k f_k(\mW(c_j, \vc_{-j})).
\end{aligned}
\end{equation}


Adding these two inequalities together, we find:
\[
(c_j' - c_j) \left[f_j(\mW(c_j', \vc_{-j})) - f_j(\mW(c_j, \vc_{-j}))\right] \leq 0.
\]
Since by assumption $c_j' > c_j$, it must be the case that:
\[
f_j(\mW(c_j', \vc_{-j})) \leq f_j(\mW(c_j, \vc_{-j})),
\]
contradicting our initial assumption. Therefore, the function $f_j$ is monotonically non-increasing in the seller's reported cost $c_j$




\subsubsection{Proof for Theorem~\ref{thm - Myerson-smallest}}
\label{app: Proof-Myerson-smallest-payment}
\begin{proof}
    From the IC condition, we have
    \begin{equation}
        p(c_j) - c_jf_j(c_j) \geq p(c_j') - c_jf_j(c_j'),
    \end{equation}
     \begin{equation}
        p(c_j') - c_j'f_j(c_j') \geq p(c_j) - c_j'f_j(c_j),
    \end{equation}
    \begin{equation}
        c_j'[f(c_j)-f(c_j')] \geq p(c_j)-p(c_j') \geq c_j[f(c_j)-f(c_j')]
    \end{equation} 
    Let $c_j' = u$, and $c_j = u+h$, with $h \rightarrow 0_+$, we have
    \begin{equation}
        (u+h) f'(u) \geq p'(u) \geq uf'(u)
    \end{equation}
    and thus
    \begin{equation}
        uf'(u) = p'(u)
    \end{equation}
    We have 
    \begin{equation}
    \begin{aligned}
         p(u) = \int_{\infty}^u p'(u) & = \int_{\infty}^u uf'(u) \\
         & = uf(u) -\int_{\infty}^u f(u) du \\
         & = uf(u) + \int_u^{\infty} f(u) du + C
    \end{aligned}
    \end{equation}
    Constrained to IR, we have $C \geq 0$. Myerson payment is when $C$ is chosen as $0$.
\end{proof}






\subsubsection{Proof for Theorem~\ref{thm - impossibility result}}
\label{app: proof-impossibility-result}
We consider a simple one-buyer-one-seller case, where the reported valuations are 
\begin{equation}
    \hat{v}_b = \hat{l}_b(0) - \hat{l}_b(w_{bs}^\star) ,\:  \hat{v}_s = - \hat{c}_s f(w_{bs}^\star)
\end{equation}
where $w_{bs}^\star \in \argmin  \hat{l}_b(0) - \hat{l}_b(w_{bs}^\star) - \hat{c}(w_{bs}^\star)$.
Truthfulness requires Groves payment rule, thus $p_b = h(v_s)-v_s$ and $ p_s=h(v_b)-v_b$. With truthful reporting, we have social efficiency directly follows as the coordinator chooses socially optimal $\mW$. 

Now we check IR and WBB conditions, with IR, we have
\begin{equation}
    v_b+v_s \geq \max(h(v_b),h(v_s))
\end{equation}
With WBB, we have 
\begin{equation}
\label{cond: wbb}
    v_b+v_s \leq h(v_b)+h(v_s)
\end{equation}

Let  $v_b \rightarrow 0$, we have $v_s \geq \max(h(0),h(v_s))$. This implies $v_s \geq h(v_s)$. Analogously, $v_b \geq h(v_b)$.

Let $\delta_b = v_b -h(v_b)$ and $\delta_s = v_s -h(v_s)$, we have $\delta_b \geq 0$ and $\delta_s \geq 0$. Plugging in (\ref{cond: wbb}), we have 
\[
\delta_b +\delta_s + h(v_b)+h(v_s) \leq h(v_b)+h(v_s)
\]
which suggests $\delta_b +\delta_s \leq 0$. It can only be $\delta_b = \delta_s =0$.
That is, $p_b = p_s =0$. Both the buyer and the seller only take their own valuations into account. As the seller's valuation will be negative as long as $w_{bs}>0$, constrained to IR conditions, there will not be trade happening. 

Now let's check the Price of Anarchy (PoA):
\begin{equation}
    PoA = \frac{l_b(0)}{\min_{w_{bs}} l_b(w_{bs}) + c_s f(w_{bs})}
\end{equation}

PoA can be arbitrarily large if $\min_{w_{bs}} l_b(w_{bs}) + c_s f(w_{bs)} \rightarrow 0$, when happens when seller $s$ has exactly the data buyer $b$ needs, which makes buyer $b$'s loss goes to 0, and the cost $c_s$ is 0. 


\subsubsection{Derivation of W in Mean Estimation Market}
\label{append: W-closed-form}

We offer the proof for the derivation of closed-form $\mW$ in Section~\ref{ sec: exp-mean-est-market}.


\begin{equation}
    SC \coloneqq  \E \sum_{i \in \gB}\|\sum_{j \in \gS}w_{i,j}\hat{\vmu}_j - \vmu_i\|^2 + \sum_{j \in \gS} \hat{c}_j \sum_{i \in \gB} w_{i,j}^2
\end{equation}

\begin{equation}
\begin{aligned}
     & \E \|\sum_{j \in \gS}w_{i,j}\hat{\vmu}_j -\sum_{j \in \gS}w_{i,j}\vmu_j + \sum_{j \in \gS}w_{i,j}\vmu_j- \vmu_i\|^2 + \sum_{j \in \gS} \hat{c}_j  w_{i,j}^2 \\
     =& \sum_{j \in \gS} w^2_{i,j} \sigma_j^2 + (\sum_{j \in \gS} w_{i,j} \vmu_j)^\top(\sum_{j \in \gS} w_{i,j} \vmu_j)   \\
     & - 2 \sum_{j \in \gS} w_{i,j} \vmu_j^\top \vmu_i  + \vmu_i^\top \vmu_i + \sum_{j \in \gS} \hat{c}_j  w_{i,j}^2 \\
     = & \mW_{i,:} (\mV+\mA) \mW_{i,:}^\top + \mW_{i,:} \mC \mW_{i,:}^\top - 2 \mW_{i,:} \mB_{i,:}^\top+ \vmu_i^\top \vmu_i
\end{aligned}
\end{equation}

We have 
\[
\mW_{i,:}^\top = (\mV+\mA+\mC)^{-1} \mB_{i,:}^\top
\]

Thus,
\[
\mW = \mB(\mV+\mA+\mC)^{-1} 
\]

\[
SC = \sum_{i \in \gB} \left[\vmu_i^\top \vmu_i -  \mB_{i,:}(\mV+\mA+\mC)^{-1} \mB_{i,:}^\top \right]
\]


